{
  "name": "migrateai-analyzer",
  "version": "0.1.0",
  "private": true,
  "description": "MigrateAI repository scanner (MongoDB/Mongoose detection) and Agent 1 dependency graph extractor",
  "main": "dist/cli.js",
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "vitest run",
    "analyze": "node dist/cli.js"
  },
  "dependencies": {
    "@babel/parser": "^7.24.0"
  },
  "devDependencies": {
    "@types/node": "^20.11.0",
    "typescript": "^5.4.0",
    "vitest": "^2.0.0"
  }
}

// Shared JSON contract between the analyzer, the FastAPI backend and the dashboard.

export type Category =
  | 'Dependencies'
  | 'Connection'
  | 'Schema'
  | 'Model'
  | 'Queries'
  | 'Relationships'
  | 'Database operations';

export type Confidence = 'high' | 'medium' | 'low';

export interface Finding {
  file: string; // repo-relative, forward slashes
  line: number;
  column: number;
  category: Category;
  pattern: string; // what was matched, e.g. "User.find()"
  evidence: string; // the source line
  confidence: Confidence;
  detail?: string; // e.g. model name or referenced model
}

export type NodeKind = 'entry' | 'route' | 'controller' | 'service' | 'model' | 'database' | 'file';
export type EdgeType = 'imports' | 'registers_route' | 'calls_service' | 'uses_model' | 'connects_db';
export type Impact = 'direct' | 'indirect' | 'none';

export interface GraphNode {
  id: string; // repo-relative path
  label: string; // file name
  path: string;
  kind: NodeKind;
  mongo: boolean; // contains MongoDB/Mongoose code
  impact: Impact; // direct = has Mongo code, indirect = depends on a file that does
  categories: Category[];
  findingCount: number;
  models: string[]; // Mongoose model names defined in this file
}

export interface GraphEdge {
  id: string;
  source: string; // the importing file
  target: string; // the imported file
  type: EdgeType;
  label?: string;
}

export interface Graph {
  nodes: GraphNode[];
  edges: GraphEdge[];
  // model file -> files that (transitively) depend on it, nearest first
  impact: Record<string, string[]>;
}

export interface AffectedFile {
  file: string;
  kind: NodeKind;
  findingCount: number;
  categories: Category[];
}

export interface Summary {
  filesScanned: number;
  filesWithFindings: number;
  totalFindings: number;
  byCategory: Record<string, number>;
  byConfidence: Record<string, number>;
  modelCount: number;
  models: string[];
  driver: 'mongoose' | 'mongodb' | 'both' | 'none';
  parseFailures: number;
  truncated: boolean;
  nodeCount: number;
  edgeCount: number;
  durationMs: number;
}

export interface AnalysisResult {
  summary: Summary;
  findings: Finding[];
  affectedFiles: AffectedFile[];
  graph: Graph | null;
  warnings: string[];
}

// ---- internal types ----

export interface ImportRef {
  specifier: string;
  kind: 'import' | 'require' | 'dynamic' | 'export-from';
  line: number;
  column: number;
}

export interface Binding {
  local: string;
  source: string;
  imported: string; // 'default' | '*' | named export
  line: number;
}

export interface CallCandidate {
  rootName: string | null;
  rootText: string;
  methods: string[];
  opIndex: number;
  op: string;
  category: 'Queries' | 'Database operations' | 'Relationships';
  line: number;
  column: number;
  evidence: string;
  hints: string[];
  viaModelCall: boolean;
}

export interface Registration {
  kind: 'use' | 'handler';
  binding: string | null;
  specifier: string | null;
  path: string | null;
  method: string | null;
  line: number;
}

export interface FileAnalysis {
  path: string;
  imports: ImportRef[];
  bindings: Binding[];
  findings: Finding[];
  candidates: CallCandidate[];
  registrations: Registration[];
  localModels: Record<string, string>;
  docVars: Record<string, string>;
  flags: { listen: boolean; expressCall: boolean; routerCall: boolean; routeCalls: number };
  usesMongoLib: boolean;
  models: string[];
  dynamicImports: number;
  parseError?: string;
}

// Detection rules and scan limits. These are evidence patterns, not proof of MongoDB usage.

export const MONGO_PACKAGES = ['mongoose', 'mongodb'] as const;

// Mongoose / driver query-style methods.
export const QUERY_METHODS = new Set([
  'find',
  'findOne',
  'findById',
  'findOneAndUpdate',
  'findOneAndDelete',
  'findOneAndReplace',
  'findByIdAndUpdate',
  'findByIdAndDelete',
  'findByIdAndRemove',
  'save',
  'create',
  'exists',
]);

// Write / aggregate operations typical of the native driver and Mongoose models.
export const DB_OP_METHODS = new Set([
  'insertOne',
  'insertMany',
  'updateOne',
  'updateMany',
  'replaceOne',
  'deleteOne',
  'deleteMany',
  'bulkWrite',
  'aggregate',
  'distinct',
  'countDocuments',
  'estimatedDocumentCount',
]);

export const FIND_FAMILY = new Set([
  'find',
  'findOne',
  'findById',
  'findOneAndUpdate',
  'findOneAndDelete',
  'findByIdAndUpdate',
  'findByIdAndDelete',
]);

// Chain methods that are strongly Mongoose-flavoured when combined with find*.
export const MONGOOSE_CHAIN_HINTS = new Set(['populate', 'lean', 'exec']);

export const ROUTE_METHODS = new Set(['get', 'post', 'put', 'delete', 'patch', 'all']);

export const SKIP_DIRS = new Set([
  'node_modules',
  'dist',
  'build',
  'coverage',
  'out',
  'vendor',
  '__pycache__',
  'venv',
]);

export const SOURCE_EXTS = new Set(['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs']);

export const GENERATED_PATTERNS = [/\.min\.js$/, /\.bundle\.js$/, /\.d\.ts$/, /\.chunk\.js$/];

export const LIMITS = {
  maxFiles: 5000,
  maxFileBytes: 1_000_000,
  maxTotalBytes: 100_000_000,
  timeMs: 60_000,
  maxGraphNodes: 400,
};

// Last-resort line patterns for files that cannot be parsed. Always low confidence.
export const FALLBACK_PATTERNS: { category: string; pattern: string; regex: RegExp }[] = [
  { category: 'Dependencies', pattern: "require/import 'mongoose' or 'mongodb'", regex: /(?:require\(\s*|from\s+)['"](?:mongoose|mongodb)['"]/ },
  { category: 'Connection', pattern: 'mongoose.connect()', regex: /\bmongoose\.(?:connect|createConnection)\s*\(/ },
  { category: 'Connection', pattern: 'MongoClient', regex: /\bMongoClient\b/ },
  { category: 'Schema', pattern: 'new Schema()', regex: /\bnew\s+(?:mongoose\.)?Schema\s*\(/ },
  { category: 'Model', pattern: 'mongoose.model()', regex: /\bmongoose\.model\s*\(/ },
  { category: 'Relationships', pattern: 'populate()', regex: /\.populate\s*\(/ },
];

import { parse } from '@babel/parser';

// Minimal structural AST node type (Babel AST, accessed loosely).
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type Node = { type: string; loc?: any; [key: string]: any };

const SKIP_KEYS = new Set(['loc', 'start', 'end', 'extra', 'leadingComments', 'trailingComments', 'innerComments', 'errors', 'tokens']);

export function walk(node: Node | null | undefined, visit: (n: Node, parent: Node | null) => void, parent: Node | null = null): void {
  if (!node || typeof node.type !== 'string') return;
  visit(node, parent);
  for (const key of Object.keys(node)) {
    if (SKIP_KEYS.has(key)) continue;
    const value = node[key];
    if (Array.isArray(value)) {
      for (const child of value) {
        if (child && typeof child.type === 'string') walk(child, visit, node);
      }
    } else if (value && typeof value.type === 'string') {
      walk(value, visit, node);
    }
  }
}

function pluginSets(filename: string): string[][] {
  const lower = filename.toLowerCase();
  if (lower.endsWith('.tsx')) return [['typescript', 'jsx', 'decorators-legacy']];
  if (lower.endsWith('.ts') || lower.endsWith('.mts') || lower.endsWith('.cts')) return [['typescript', 'decorators-legacy']];
  return [['jsx', 'decorators-legacy'], ['jsx', 'flow'], ['typescript', 'jsx', 'decorators-legacy']];
}

/** Parse source text without executing it. Returns the Program node, or null if it cannot be parsed. */
export function parseSource(code: string, filename: string): Node | null {
  let best: { program: Node; errors: number } | null = null;
  for (const plugins of pluginSets(filename)) {
    try {
      const file = parse(code, {
        sourceType: 'unambiguous',
        errorRecovery: true,
        allowReturnOutsideFunction: true,
        allowImportExportEverywhere: true,
        allowAwaitOutsideFunction: true,
        allowSuperOutsideMethod: true,
        allowUndeclaredExports: true,
        plugins: plugins as never,
      }) as unknown as Node;
      const errors = Array.isArray(file.errors) ? file.errors.length : 0;
      if (errors === 0) return file.program;
      if (!best || errors < best.errors) best = { program: file.program, errors };
    } catch {
      // try the next plugin set
    }
  }
  return best ? best.program : null;
}

export function strValue(n: Node | null | undefined): string | null {
  if (!n) return null;
  if (n.type === 'StringLiteral') return n.value as string;
  if (n.type === 'TemplateLiteral' && n.expressions.length === 0 && n.quasis.length === 1) {
    return (n.quasis[0].value.cooked as string) ?? null;
  }
  return null;
}

export function propName(member: Node): string | null {
  if (!member.computed && member.property?.type === 'Identifier') return member.property.name as string;
  if (member.property?.type === 'StringLiteral') return member.property.value as string;
  return null;
}

export interface ChainInfo {
  root: Node | null;
  methods: { name: string; node: Node }[]; // called methods, root -> outermost
}

/** Unwind `a.b().c().d()` style chains down to the root expression. */
export function analyzeChain(expr: Node): ChainInfo {
  const methods: { name: string; node: Node }[] = [];
  let cur: Node | null | undefined = expr;
  for (let i = 0; i < 300 && cur; i++) {
    if (cur.type === 'CallExpression' || cur.type === 'OptionalCallExpression') {
      const callee: Node | undefined = cur.callee;
      if (callee && (callee.type === 'MemberExpression' || callee.type === 'OptionalMemberExpression')) {
        const name = propName(callee);
        if (name) methods.unshift({ name, node: cur });
      }
      cur = callee;
    } else if (cur.type === 'MemberExpression' || cur.type === 'OptionalMemberExpression') {
      cur = cur.object;
    } else if (cur.type === 'AwaitExpression') {
      cur = cur.argument;
    } else if (cur.type === 'TSNonNullExpression' || cur.type === 'TSAsExpression' || cur.type === 'ParenthesizedExpression') {
      cur = cur.expression;
    } else {
      break;
    }
  }
  return { root: cur ?? null, methods };
}

import * as fs from 'fs';
import * as path from 'path';
import { Node, walk, strValue, propName } from './ast';
import { Binding, ImportRef } from './types';

export interface ExtractedImports {
  imports: ImportRef[];
  bindings: Binding[];
  dynamicCount: number;
}

const pos = (n: Node) => ({ line: n.loc?.start.line ?? 0, column: (n.loc?.start.column ?? 0) + 1 });

/** Source specifier of `require('x')` or `await import('x')`, else null. */
function requireSource(node: Node | null | undefined): string | null {
  if (!node) return null;
  let n: Node = node;
  if (n.type === 'AwaitExpression') n = n.argument;
  if (n?.type !== 'CallExpression') return null;
  if (n.callee.type === 'Identifier' && n.callee.name === 'require' && n.arguments.length >= 1) return strValue(n.arguments[0]);
  if (n.callee.type === 'Import' && n.arguments.length >= 1) return strValue(n.arguments[0]);
  return null;
}

export function extractImports(program: Node): ExtractedImports {
  const imports: ImportRef[] = [];
  const bindings: Binding[] = [];
  let dynamicCount = 0;

  walk(program, (n) => {
    switch (n.type) {
      case 'ImportDeclaration': {
        const source = n.source.value as string;
        imports.push({ specifier: source, kind: 'import', ...pos(n) });
        for (const s of n.specifiers ?? []) {
          const line = pos(s).line;
          if (s.type === 'ImportDefaultSpecifier') bindings.push({ local: s.local.name, source, imported: 'default', line });
          else if (s.type === 'ImportNamespaceSpecifier') bindings.push({ local: s.local.name, source, imported: '*', line });
          else if (s.type === 'ImportSpecifier') {
            bindings.push({ local: s.local.name, source, imported: (s.imported.name ?? s.imported.value) as string, line });
          }
        }
        break;
      }
      case 'ExportNamedDeclaration':
      case 'ExportAllDeclaration':
        if (n.source) imports.push({ specifier: n.source.value as string, kind: 'export-from', ...pos(n) });
        break;
      case 'TSImportEqualsDeclaration': {
        const ref = n.moduleReference;
        if (ref?.type === 'TSExternalModuleReference') {
          const source = strValue(ref.expression);
          if (source) {
            imports.push({ specifier: source, kind: 'require', ...pos(n) });
            bindings.push({ local: n.id.name, source, imported: 'default', line: pos(n).line });
          }
        }
        break;
      }
      case 'VariableDeclarator': {
        const init: Node | null = n.init;
        if (!init) break;
        const line = pos(n).line;
        const direct = requireSource(init);
        if (direct !== null) {
          if (n.id.type === 'Identifier') {
            bindings.push({ local: n.id.name, source: direct, imported: 'default', line });
          } else if (n.id.type === 'ObjectPattern') {
            for (const p of n.id.properties) {
              if (p.type !== 'ObjectProperty' || p.key.type !== 'Identifier') continue;
              const local = p.value.type === 'Identifier' ? p.value.name : p.value.type === 'AssignmentPattern' && p.value.left.type === 'Identifier' ? p.value.left.name : null;
              if (local) bindings.push({ local, source: direct, imported: p.key.name as string, line });
            }
          }
        } else if (init.type === 'MemberExpression' && n.id.type === 'Identifier') {
          const inner = requireSource(init.object);
          const prop = propName(init);
          if (inner !== null && prop) bindings.push({ local: n.id.name, source: inner, imported: prop, line });
        }
        break;
      }
      case 'CallExpression': {
        if (n.callee.type === 'Identifier' && n.callee.name === 'require' && n.arguments.length >= 1) {
          const spec = strValue(n.arguments[0]);
          if (spec) imports.push({ specifier: spec, kind: 'require', ...pos(n) });
        } else if (n.callee.type === 'Import') {
          const spec = strValue(n.arguments[0]);
          if (spec) imports.push({ specifier: spec, kind: 'dynamic', ...pos(n) });
          else dynamicCount++;
        }
        break;
      }
      default:
        break;
    }
  });

  return { imports, bindings, dynamicCount };
}

// ---------- path resolution ----------

const EXTS = ['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs'];

export interface Resolver {
  /** Resolve an import specifier from a repo-relative file to another repo-relative file, or null. */
  resolve(from: string, specifier: string): string | null;
}

interface AliasRule {
  prefix: string;
  suffix: string;
  hasWildcard: boolean;
  targets: string[];
}

function readJsonLoose(file: string): Record<string, unknown> | null {
  try {
    const text = fs
      .readFileSync(file, 'utf8')
      .replace(/^﻿/, '')
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .replace(/^\s*\/\/.*$/gm, '')
      .replace(/,\s*([}\]])/g, '$1');
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function loadAliases(root: string): { baseUrl: string | null; rules: AliasRule[] } {
  for (const name of ['tsconfig.json', 'jsconfig.json']) {
    const cfg = readJsonLoose(path.join(root, name));
    const opts = cfg && (cfg.compilerOptions as Record<string, unknown> | undefined);
    if (!opts) continue;
    const baseUrl = typeof opts.baseUrl === 'string' ? path.posix.normalize(opts.baseUrl.replace(/\\/g, '/')) : null;
    const rules: AliasRule[] = [];
    const paths = opts.paths as Record<string, string[]> | undefined;
    if (paths && typeof paths === 'object') {
      for (const [pattern, targets] of Object.entries(paths)) {
        if (!Array.isArray(targets)) continue;
        const star = pattern.indexOf('*');
        rules.push({
          prefix: star === -1 ? pattern : pattern.slice(0, star),
          suffix: star === -1 ? '' : pattern.slice(star + 1),
          hasWildcard: star !== -1,
          targets,
        });
      }
    }
    if (baseUrl !== null || rules.length) return { baseUrl, rules };
  }
  return { baseUrl: null, rules: [] };
}

export function createResolver(root: string, files: Set<string>): Resolver {
  const aliases = loadAliases(root);

  const tryResolve = (basePath: string): string | null => {
    const base = path.posix.normalize(basePath);
    if (base.startsWith('..') || base.startsWith('/')) return null;
    const candidates = [base, ...EXTS.map((e) => base + e), ...EXTS.map((e) => `${base}/index${e}`)];
    // TypeScript ESM style: import './x.js' that actually refers to x.ts
    const m = base.match(/^(.*)\.(m|c)?jsx?$/);
    if (m) candidates.push(`${m[1]}.ts`, `${m[1]}.tsx`);
    for (const c of candidates) if (files.has(c)) return c;
    return null;
  };

  return {
    resolve(from: string, specifier: string): string | null {
      if (specifier.startsWith('.')) {
        return tryResolve(path.posix.join(path.posix.dirname(from), specifier));
      }
      for (const rule of aliases.rules) {
        if (!specifier.startsWith(rule.prefix) || !specifier.endsWith(rule.suffix)) continue;
        if (!rule.hasWildcard && specifier !== rule.prefix) continue;
        const star = specifier.slice(rule.prefix.length, specifier.length - rule.suffix.length);
        for (const target of rule.targets) {
          const mapped = rule.hasWildcard ? target.replace('*', star) : target;
          const hit = tryResolve(path.posix.join(aliases.baseUrl ?? '.', mapped));
          if (hit) return hit;
        }
      }
      if (aliases.baseUrl !== null) {
        const hit = tryResolve(path.posix.join(aliases.baseUrl, specifier));
        if (hit) return hit;
      }
      return null; // external package or unresolved alias
    },
  };
}

import * as fs from 'fs';
import * as path from 'path';
import { Node, analyzeChain, parseSource, propName, strValue, walk } from './ast';
import { extractImports } from './dependencies';
import {
  DB_OP_METHODS,
  FALLBACK_PATTERNS,
  GENERATED_PATTERNS,
  LIMITS,
  QUERY_METHODS,
  ROUTE_METHODS,
  SKIP_DIRS,
  SOURCE_EXTS,
} from './rules';
import { CallCandidate, Category, Confidence, FileAnalysis, Finding } from './types';

// ---------------------------------------------------------------------------
// Step 2 — collect source files (never executes anything from the repository)
// ---------------------------------------------------------------------------

export interface CollectResult {
  files: string[];
  packageJsons: string[];
  warnings: string[];
  truncated: boolean;
}

export function collectFiles(root: string, limits = LIMITS): CollectResult {
  const files: string[] = [];
  const packageJsons: string[] = [];
  const warnings: string[] = [];
  let truncated = false;
  let totalBytes = 0;
  const deadline = Date.now() + limits.timeMs;
  const stack: string[] = [''];

  outer: while (stack.length) {
    const rel = stack.pop() as string;
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(path.join(root, rel), { withFileTypes: true });
    } catch {
      warnings.push(`Could not read directory ${rel || '.'}`);
      continue;
    }
    for (const e of entries) {
      if (Date.now() > deadline) {
        truncated = true;
        warnings.push('Time limit reached; analysis is partial.');
        break outer;
      }
      if (e.isSymbolicLink()) continue; // never follow symlinks out of the repo
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      if (e.isDirectory()) {
        if (SKIP_DIRS.has(e.name) || e.name.startsWith('.')) continue;
        stack.push(childRel);
        continue;
      }
      if (!e.isFile()) continue;
      if (e.name === 'package.json') {
        packageJsons.push(childRel);
        continue;
      }
      if (!SOURCE_EXTS.has(path.extname(e.name).toLowerCase())) continue;
      if (GENERATED_PATTERNS.some((r) => r.test(e.name))) continue;
      let size = 0;
      try {
        size = fs.statSync(path.join(root, childRel)).size;
      } catch {
        continue;
      }
      if (size > limits.maxFileBytes) {
        warnings.push(`Skipped large file ${childRel}`);
        continue;
      }
      if (files.length >= limits.maxFiles || totalBytes + size > limits.maxTotalBytes) {
        truncated = true;
        warnings.push('File limit reached; analysis is partial.');
        break outer;
      }
      files.push(childRel);
      totalBytes += size;
    }
  }

  files.sort();
  packageJsons.sort();
  return { files, packageJsons, warnings, truncated };
}

// ---------------------------------------------------------------------------
// Step 3 — detect MongoDB usage (pattern evidence + AST context)
// ---------------------------------------------------------------------------

const isPkg = (spec: string, name: string) => spec === name || spec.startsWith(`${name}/`);

function categoryOf(method: string): CallCandidate['category'] | null {
  if (QUERY_METHODS.has(method)) return 'Queries';
  if (DB_OP_METHODS.has(method)) return 'Database operations';
  if (method === 'populate') return 'Relationships';
  return null;
}

function emptyAnalysis(rel: string): FileAnalysis {
  return {
    path: rel,
    imports: [],
    bindings: [],
    findings: [],
    candidates: [],
    registrations: [],
    localModels: {},
    docVars: {},
    flags: { listen: false, expressCall: false, routerCall: false, routeCalls: 0 },
    usesMongoLib: false,
    models: [],
    dynamicImports: 0,
  };
}

export function analyzeFile(code: string, rel: string): FileAnalysis {
  const lines = code.replace(/^﻿/, '').split(/\r?\n/);
  const result = emptyAnalysis(rel);
  const program = parseSource(code, rel);
  if (!program) {
    result.parseError = 'syntax could not be parsed';
    fallbackScan(lines, result);
    return result;
  }
  try {
    astPass(program, result, lines);
  } catch (err) {
    result.parseError = err instanceof Error ? err.message : 'analysis failed';
    result.findings = [];
    fallbackScan(lines, result);
  }
  return result;
}

function fallbackScan(lines: string[], a: FileAnalysis): void {
  lines.forEach((text, i) => {
    for (const rule of FALLBACK_PATTERNS) {
      if (rule.regex.test(text)) {
        a.findings.push({
          file: a.path,
          line: i + 1,
          column: 1,
          category: rule.category as Category,
          pattern: rule.pattern,
          evidence: text.trim().slice(0, 160),
          confidence: 'low',
        });
        if (rule.category === 'Dependencies' || rule.category === 'Connection') a.usesMongoLib = true;
      }
    }
    // Minimal import extraction so the graph still has edges for unparsable files.
    const re = /(?:require\(\s*|from\s+)['"](\.{1,2}\/[^'"]+)['"]/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(text))) a.imports.push({ specifier: m[1], kind: 'import', line: i + 1, column: m.index + 1 });
  });
}

function astPass(program: Node, a: FileAnalysis, lines: string[]): void {
  const ev = (line: number) => (lines[line - 1] ?? '').trim().slice(0, 160);
  const loc = (n: Node) => ({ line: n.loc?.start.line ?? 0, column: (n.loc?.start.column ?? 0) + 1 });
  const add = (category: Category, pattern: string, n: Node, confidence: Confidence, detail?: string) => {
    const { line, column } = loc(n);
    a.findings.push({ file: a.path, line, column, category, pattern, evidence: ev(line), confidence, detail });
  };

  const { imports, bindings, dynamicCount } = extractImports(program);
  a.imports = imports;
  a.bindings = bindings;
  a.dynamicImports = dynamicCount;

  const mongooseNs = new Set<string>();
  const mongodbNs = new Set<string>();
  const mongooseNamed = new Map<string, string>(); // local -> exported name
  const mongodbNamed = new Map<string, string>();
  for (const b of bindings) {
    if (isPkg(b.source, 'mongoose')) {
      if (b.imported === 'default' || b.imported === '*') mongooseNs.add(b.local);
      else mongooseNamed.set(b.local, b.imported);
    } else if (isPkg(b.source, 'mongodb')) {
      if (b.imported === 'default' || b.imported === '*') mongodbNs.add(b.local);
      else mongodbNamed.set(b.local, b.imported);
    }
  }
  a.usesMongoLib = imports.some((i) => isPkg(i.specifier, 'mongoose') || isPkg(i.specifier, 'mongodb'));

  // Dependencies: import / require of the packages.
  for (const imp of imports) {
    if (isPkg(imp.specifier, 'mongoose') || isPkg(imp.specifier, 'mongodb')) {
      a.findings.push({
        file: a.path,
        line: imp.line,
        column: imp.column,
        category: 'Dependencies',
        pattern: imp.kind === 'require' ? `require('${imp.specifier}')` : `import '${imp.specifier}'`,
        evidence: ev(imp.line),
        confidence: 'high',
        detail: imp.specifier,
      });
    }
  }

  const connVars = new Set<string>();
  const localModels = new Map<string, string>();
  const docVars = new Map<string, string>();
  const refs: { node: Node; target: string }[] = [];
  const seenCandidates = new Set<string>();

  const unwrap = (n: Node | null | undefined): Node | null => {
    let cur = n ?? null;
    while (cur && (cur.type === 'AwaitExpression' || cur.type === 'TSAsExpression' || cur.type === 'TSNonNullExpression' || cur.type === 'ParenthesizedExpression')) {
      cur = (cur.argument ?? cur.expression) as Node;
    }
    return cur;
  };

  const isConnectionFactory = (call: Node): boolean => {
    const c = call.callee;
    if (c.type === 'MemberExpression' && c.object.type === 'Identifier') {
      return mongooseNs.has(c.object.name) && propName(c) === 'createConnection';
    }
    return c.type === 'Identifier' && mongooseNamed.get(c.name) === 'createConnection';
  };

  const modelCall = (call: Node): { conf: Confidence; name: string } | null => {
    const callee = call.callee;
    const first = strValue(call.arguments?.[0]);
    if (callee.type === 'MemberExpression' && propName(callee) === 'model' && callee.object.type === 'Identifier') {
      const o = callee.object.name as string;
      if (mongooseNs.has(o) || connVars.has(o)) return { conf: 'high', name: first ?? 'unknown' };
      if (a.usesMongoLib && first !== null && call.arguments.length >= 2) return { conf: 'medium', name: first };
    } else if (callee.type === 'Identifier' && mongooseNamed.get(callee.name) === 'model') {
      return { conf: 'high', name: first ?? 'unknown' };
    }
    return null;
  };

  const findModelCallIn = (n: Node | null | undefined): Node | null => {
    const cur = unwrap(n);
    if (!cur) return null;
    if (cur.type === 'CallExpression' && modelCall(cur)) return cur;
    if (cur.type === 'LogicalExpression') return findModelCallIn(cur.left) ?? findModelCallIn(cur.right);
    if (cur.type === 'ConditionalExpression') return findModelCallIn(cur.consequent) ?? findModelCallIn(cur.alternate);
    return null;
  };

  const argRoot = (arg: Node): { binding: string | null; specifier: string | null } => {
    if (arg.type === 'Identifier') return { binding: arg.name, specifier: null };
    if (arg.type === 'MemberExpression') {
      const r = analyzeChain(arg).root;
      if (r?.type === 'Identifier') return { binding: r.name, specifier: null };
    }
    if (arg.type === 'CallExpression') {
      if (arg.callee.type === 'Identifier' && arg.callee.name === 'require') {
        return { binding: null, specifier: strValue(arg.arguments[0]) };
      }
      if (arg.callee.type === 'Identifier') return { binding: arg.callee.name, specifier: null };
    }
    return { binding: null, specifier: null };
  };

  walk(program, (n, parent) => {
    switch (n.type) {
      case 'VariableDeclarator': {
        const init: Node | null = n.init;
        if (!init) break;
        const target = n.id;
        if (init.type === 'Identifier' && mongooseNs.has(init.name) && target.type === 'ObjectPattern') {
          for (const p of target.properties) {
            if (p.type === 'ObjectProperty' && p.key.type === 'Identifier' && p.value.type === 'Identifier') {
              mongooseNamed.set(p.value.name, p.key.name);
            }
          }
        }
        if (init.type === 'MemberExpression' && init.object.type === 'Identifier' && mongooseNs.has(init.object.name) && target.type === 'Identifier') {
          const prop = propName(init);
          if (prop === 'connection') connVars.add(target.name);
          else if (prop) mongooseNamed.set(target.name, prop);
        }
        if (target.type !== 'Identifier') break;
        const inner = unwrap(init);
        if (inner?.type === 'CallExpression' && isConnectionFactory(inner)) connVars.add(target.name);
        const mc = findModelCallIn(init);
        if (mc) {
          const info = modelCall(mc);
          if (info) localModels.set(target.name, info.name);
        }
        if (inner?.type === 'NewExpression' && inner.callee.type === 'Identifier') {
          docVars.set(target.name, inner.callee.name);
        } else if (inner) {
          const chain = analyzeChain(inner);
          if (chain.root?.type === 'Identifier' && chain.methods.some((m) => QUERY_METHODS.has(m.name) && m.name !== 'save')) {
            docVars.set(target.name, chain.root.name);
          }
        }
        break;
      }

      case 'ObjectProperty': {
        const keyName = n.key.type === 'Identifier' ? n.key.name : n.key.type === 'StringLiteral' ? n.key.value : null;
        const target = strValue(n.value);
        if (keyName === 'ref' && target) refs.push({ node: n, target });
        break;
      }

      case 'NewExpression': {
        const c = n.callee;
        if (c.type === 'Identifier') {
          if (mongooseNamed.get(c.name) === 'Schema') add('Schema', 'new Schema()', n, 'high');
          else if (mongodbNamed.get(c.name) === 'MongoClient') add('Connection', 'new MongoClient()', n, 'high');
        } else if (c.type === 'MemberExpression' && c.object.type === 'Identifier') {
          const prop = propName(c);
          if (mongooseNs.has(c.object.name) && prop === 'Schema') add('Schema', `new ${c.object.name}.Schema()`, n, 'high');
          else if (mongodbNs.has(c.object.name) && prop === 'MongoClient') add('Connection', `new ${c.object.name}.MongoClient()`, n, 'high');
        }
        break;
      }

      case 'CallExpression':
      case 'OptionalCallExpression': {
        const callee: Node = n.callee;

        // --- connection / model / route detection ---
        if (callee.type === 'MemberExpression' && callee.object.type === 'Identifier') {
          const obj = callee.object.name as string;
          const prop = propName(callee);
          if (mongooseNs.has(obj) && (prop === 'connect' || prop === 'createConnection')) {
            add('Connection', `${obj}.${prop}()`, n, 'high');
          } else if (mongodbNamed.get(obj) === 'MongoClient' && prop === 'connect') {
            add('Connection', `${obj}.connect()`, n, 'high');
          }
          const mc = modelCall(n);
          if (mc) {
            add('Model', `${obj}.model()`, n, mc.conf, mc.name);
            a.models.push(mc.name);
          }
        } else if (callee.type === 'Identifier') {
          const named = mongooseNamed.get(callee.name);
          if (named === 'connect' || named === 'createConnection') add('Connection', `${callee.name}()`, n, 'high');
          const mc = modelCall(n);
          if (mc) {
            add('Model', `${callee.name}()`, n, mc.conf, mc.name);
            a.models.push(mc.name);
          }
          if (callee.name === 'express') a.flags.expressCall = true;
          if (callee.name === 'Router') a.flags.routerCall = true;
        }

        if (callee.type === 'MemberExpression') {
          const prop = propName(callee);
          if (prop === 'Router') a.flags.routerCall = true;
          if (prop === 'listen' && n.arguments.length >= 1) a.flags.listen = true;

          if (prop === 'use' && n.arguments.length >= 1) {
            const first = strValue(n.arguments[0]);
            for (const arg of n.arguments as Node[]) {
              const r = argRoot(arg);
              if (r.binding || r.specifier) {
                a.registrations.push({ kind: 'use', binding: r.binding, specifier: r.specifier, path: first, method: 'USE', line: loc(n).line });
              }
            }
          } else if (prop && ROUTE_METHODS.has(prop) && n.arguments.length >= 2) {
            const p = strValue(n.arguments[0]);
            if (p !== null && p.startsWith('/')) {
              a.flags.routeCalls++;
              for (const arg of (n.arguments as Node[]).slice(1)) {
                const r = argRoot(arg);
                if (r.binding || r.specifier) {
                  a.registrations.push({ kind: 'handler', binding: r.binding, specifier: r.specifier, path: p, method: prop.toUpperCase(), line: loc(n).line });
                }
              }
            }
          }
        }

        // --- query / operation / relationship candidates (outermost call of a chain) ---
        const isInner = parent && (parent.type === 'MemberExpression' || parent.type === 'OptionalMemberExpression') && parent.object === n;
        if (isInner) break;
        const chain = analyzeChain(n);
        const names = chain.methods.map((m) => m.name);
        chain.methods.forEach((m, idx) => {
          const category = categoryOf(m.name);
          if (!category) return;
          const { line, column } = loc(m.node);
          const key = `${line}:${column}:${m.name}`;
          if (seenCandidates.has(key)) return;
          seenCandidates.add(key);
          const root = chain.root;
          const rootName = root?.type === 'Identifier' ? (root.name as string) : null;
          const rootText = rootName ?? (root?.type === 'ThisExpression' ? 'this' : '(expr)');
          a.candidates.push({
            rootName,
            rootText,
            methods: names,
            opIndex: idx,
            op: m.name,
            category,
            line,
            column,
            evidence: ev(line),
            hints: names,
            viaModelCall: !!rootName && mongooseNs.has(rootName) && names.slice(0, idx).includes('model'),
          });
        });
        break;
      }

      default:
        break;
    }
  });

  // Relationships declared in schemas (`ref: 'User'`).
  const hasSchema = a.findings.some((f) => f.category === 'Schema');
  if (hasSchema || a.usesMongoLib) {
    for (const r of refs) add('Relationships', `ref: '${r.target}'`, r.node, hasSchema ? 'high' : 'medium', r.target);
  }

  a.localModels = Object.fromEntries(localModels);
  a.docVars = Object.fromEntries(docVars);
  a.models = Array.from(new Set(a.models));
}

// Agent 1 — Dependency Graph.
// Builds file-level nodes and directed "depends on" edges from real import/require statements,
// then marks which files contain MongoDB code and which files are affected if those change.

import * as path from 'path';
import { Resolver } from './dependencies';
import { LIMITS } from './rules';
import { EdgeType, FileAnalysis, Finding, Graph, GraphEdge, GraphNode, Impact, NodeKind } from './types';

export interface GraphBuildResult {
  graph: Graph;
  kinds: Map<string, NodeKind>;
  warnings: string[];
}

export function buildGraph(
  analyses: FileAnalysis[],
  findingsByFile: Map<string, Finding[]>,
  modelFiles: Map<string, string[]>,
  resolver: Resolver,
  scope: 'relevant' | 'all',
): GraphBuildResult {
  const warnings: string[] = [];
  const byPath = new Map(analyses.map((a) => [a.path, a]));

  // 1. Resolve imports into file -> file dependencies.
  const deps = new Map<string, Set<string>>(); // importer -> imported
  const reverse = new Map<string, Set<string>>(); // imported -> importers
  const routeLabels = new Map<string, Set<string>>(); // "src->dst" -> route paths registered
  const registered = new Set<string>(); // "src->dst" that are app.use(...) registrations
  let unresolved = 0;

  for (const a of analyses) {
    const out = new Set<string>();
    for (const imp of a.imports) {
      const target = resolver.resolve(a.path, imp.specifier);
      if (target && target !== a.path) out.add(target);
      else if (!target && imp.specifier.startsWith('.')) unresolved++;
    }
    deps.set(a.path, out);
    for (const t of out) {
      if (!reverse.has(t)) reverse.set(t, new Set());
      reverse.get(t)!.add(a.path);
    }
    for (const r of a.registrations) {
      let spec = r.specifier;
      if (!spec && r.binding) spec = a.bindings.find((b) => b.local === r.binding)?.source ?? null;
      if (!spec) continue;
      const target = resolver.resolve(a.path, spec);
      if (!target) continue;
      const key = `${a.path}->${target}`;
      if (r.kind === 'use') registered.add(key);
      if (r.path) {
        if (!routeLabels.has(key)) routeLabels.set(key, new Set());
        routeLabels.get(key)!.add(r.path);
      }
    }
  }
  if (unresolved > 0) warnings.push(`${unresolved} relative import(s) could not be resolved to a source file (non-JS/TS targets or dynamic paths).`);
  const dynamicTotal = analyses.reduce((s, a) => s + a.dynamicImports, 0);
  if (dynamicTotal > 0) warnings.push(`${dynamicTotal} dynamic import(s) with non-literal paths were not followed. The graph is a static approximation, not a complete dependency list.`);

  // 2. Classify each file.
  const kinds = new Map<string, NodeKind>();
  for (const a of analyses) {
    const findings = findingsByFile.get(a.path) ?? [];
    const importsModel = Array.from(deps.get(a.path) ?? []).some((t) => modelFiles.has(t));
    let kind: NodeKind = 'file';
    if (modelFiles.has(a.path)) kind = 'model';
    else if (a.flags.listen || a.flags.expressCall) kind = 'entry';
    else if (a.flags.routerCall || a.flags.routeCalls > 0) kind = 'route';
    else if (findings.some((f) => f.category === 'Connection')) kind = 'database';
    else if (/(^|\/)controllers?\//i.test(a.path) || /controller\.[jt]sx?$/i.test(a.path)) kind = 'controller';
    else if (/(^|\/)services?\//i.test(a.path) || /service\.[jt]sx?$/i.test(a.path) || importsModel) kind = 'service';
    kinds.set(a.path, kind);
  }

  // 3. Impact analysis: which files depend (transitively) on Mongo-touching files?
  const mongoFiles = new Set(analyses.filter((a) => (findingsByFile.get(a.path) ?? []).length > 0).map((a) => a.path));
  const bfsReverse = (starts: Iterable<string>, limit = Infinity): string[] => {
    const seen = new Set<string>(starts);
    const order: string[] = [];
    let frontier = Array.from(seen);
    while (frontier.length && order.length < limit) {
      const next: string[] = [];
      for (const f of frontier) {
        for (const importer of reverse.get(f) ?? []) {
          if (!seen.has(importer)) {
            seen.add(importer);
            order.push(importer);
            next.push(importer);
          }
        }
      }
      frontier = next;
    }
    return order;
  };
  const indirect = new Set(bfsReverse(mongoFiles));
  const impactOf = (p: string): Impact => (mongoFiles.has(p) ? 'direct' : indirect.has(p) ? 'indirect' : 'none');

  const impact: Record<string, string[]> = {};
  for (const [file, kind] of kinds) {
    if (kind === 'model') impact[file] = bfsReverse([file], 200);
  }

  // 4. Choose which files become nodes.
  let included: string[];
  if (scope === 'all') {
    included = analyses.map((a) => a.path);
  } else {
    included = analyses.filter((a) => impactOf(a.path) !== 'none').map((a) => a.path);
    if (included.length === 0) {
      included = analyses.map((a) => a.path);
      warnings.push('No MongoDB usage was detected, so the full import graph is shown.');
    }
  }
  if (included.length > LIMITS.maxGraphNodes) {
    const rank = (p: string) => (impactOf(p) === 'direct' ? 0 : impactOf(p) === 'indirect' ? 1 : 2);
    included = included.sort((x, y) => rank(x) - rank(y) || x.localeCompare(y)).slice(0, LIMITS.maxGraphNodes);
    warnings.push(`Graph limited to ${LIMITS.maxGraphNodes} nodes; MongoDB-related files were kept first.`);
  }
  const includedSet = new Set(included);

  // 5. Nodes.
  const nodes: GraphNode[] = included
    .sort((x, y) => x.localeCompare(y))
    .map((p) => {
      const f = findingsByFile.get(p) ?? [];
      return {
        id: p,
        label: path.posix.basename(p),
        path: p,
        kind: kinds.get(p) ?? 'file',
        mongo: f.length > 0,
        impact: impactOf(p),
        categories: Array.from(new Set(f.map((x) => x.category))),
        findingCount: f.length,
        models: byPath.get(p)?.models ?? [],
      };
    });

  // 6. Edges (importer -> imported), typed from what each side is.
  const edges: GraphEdge[] = [];
  for (const [src, targets] of deps) {
    if (!includedSet.has(src)) continue;
    for (const dst of targets) {
      if (!includedSet.has(dst)) continue;
      const sk = kinds.get(src) ?? 'file';
      const tk = kinds.get(dst) ?? 'file';
      const key = `${src}->${dst}`;
      let type: EdgeType = 'imports';
      let label: string | undefined;
      if (tk === 'model' && sk !== 'model') {
        type = 'uses_model';
        label = (modelFiles.get(dst) ?? []).slice(0, 3).join(', ') || undefined;
      } else if (tk === 'route' && registered.has(key)) {
        type = 'registers_route';
        label = Array.from(routeLabels.get(key) ?? []).slice(0, 3).join(', ') || undefined;
      } else if (tk === 'database' && sk !== 'database') {
        type = 'connects_db';
      } else if ((sk === 'route' || sk === 'controller' || sk === 'service') && (tk === 'service' || tk === 'controller')) {
        type = 'calls_service';
      }
      edges.push({ id: key, source: src, target: dst, type, label });
    }
  }
  edges.sort((x, y) => x.id.localeCompare(y.id));

  return { graph: { nodes, edges, impact }, kinds, warnings };
}

import * as fs from 'fs';
import * as path from 'path';
import { createResolver, Resolver } from './dependencies';
import { buildGraph } from './graph';
import { FIND_FAMILY, MONGOOSE_CHAIN_HINTS } from './rules';
import { analyzeFile, collectFiles } from './scanner';
import { AffectedFile, AnalysisResult, CallCandidate, Category, Confidence, FileAnalysis, Finding, NodeKind, Summary } from './types';

export interface AnalyzeOptions {
  scope?: 'relevant' | 'all';
  generateGraph?: boolean;
}

function packageJsonFindings(root: string, rel: string): { findings: Finding[]; deps: string[] } {
  const findings: Finding[] = [];
  const deps: string[] = [];
  let text: string;
  try {
    text = fs.readFileSync(path.join(root, rel), 'utf8').replace(/^﻿/, '');
  } catch {
    return { findings, deps };
  }
  let json: Record<string, Record<string, string>>;
  try {
    json = JSON.parse(text);
  } catch {
    return { findings, deps };
  }
  const lines = text.split(/\r?\n/);
  for (const section of ['dependencies', 'devDependencies', 'peerDependencies', 'optionalDependencies']) {
    const block = json[section];
    if (!block || typeof block !== 'object') continue;
    for (const name of ['mongoose', 'mongodb']) {
      if (!(name in block)) continue;
      deps.push(name);
      const idx = lines.findIndex((l) => l.includes(`"${name}"`));
      findings.push({
        file: rel,
        line: idx === -1 ? 1 : idx + 1,
        column: 1,
        category: 'Dependencies',
        pattern: `${section}.${name}`,
        evidence: idx === -1 ? `"${name}": "${block[name]}"` : lines[idx].trim().slice(0, 160),
        confidence: 'high',
        detail: block[name],
      });
    }
  }
  return { findings, deps };
}

function resolvesToModel(
  a: FileAnalysis,
  name: string | null,
  modelFiles: Map<string, string[]>,
  resolver: Resolver,
  byPath: Map<string, FileAnalysis>,
  depth = 0,
): boolean {
  if (!name) return false;
  if (a.localModels[name]) return true;
  const via = a.docVars[name];
  if (via && via !== name && depth < 3) return resolvesToModel(a, via, modelFiles, resolver, byPath, depth + 1);
  const binding = a.bindings.find((b) => b.local === name);
  if (!binding) return false;
  const target = resolver.resolve(a.path, binding.source);
  if (!target) return false;
  if (modelFiles.has(target)) return true;
  // Barrel file (models/index.js) that re-exports model files.
  const barrel = byPath.get(target);
  if (barrel && /(^|\/)index\.[jt]sx?$/.test(target)) {
    return barrel.imports.some((i) => {
      const t = resolver.resolve(barrel.path, i.specifier);
      return !!t && modelFiles.has(t);
    });
  }
  return false;
}

function confidenceFor(c: CallCandidate, a: FileAnalysis, resolved: boolean): Confidence | null {
  if (resolved || c.viaModelCall) return 'high';
  if (c.hints.includes('collection')) return a.usesMongoLib ? 'high' : 'medium';
  if (a.usesMongoLib) return 'low';
  const mongooseish = c.hints.some((h) => MONGOOSE_CHAIN_HINTS.has(h));
  const findy = c.hints.some((h) => FIND_FAMILY.has(h));
  if (mongooseish && findy) return 'medium';
  return null; // e.g. Array.prototype.find in a file with no MongoDB context
}

export function analyzeRepository(root: string, opts: AnalyzeOptions = {}): AnalysisResult {
  const started = Date.now();
  const abs = path.resolve(root);
  if (!fs.existsSync(abs) || !fs.statSync(abs).isDirectory()) throw new Error(`Not a directory: ${root}`);

  const scope = opts.scope ?? 'relevant';
  const generateGraph = opts.generateGraph ?? true;
  const collected = collectFiles(abs);
  const warnings = [...collected.warnings];
  const fileSet = new Set(collected.files);
  const resolver = createResolver(abs, fileSet);

  // Pass 1: per-file AST analysis.
  const analyses: FileAnalysis[] = [];
  let parseFailures = 0;
  for (const rel of collected.files) {
    let code: string;
    try {
      code = fs.readFileSync(path.join(abs, rel), 'utf8');
    } catch {
      warnings.push(`Could not read ${rel}`);
      continue;
    }
    const a = analyzeFile(code, rel);
    if (a.parseError) {
      parseFailures++;
      warnings.push(`${rel}: ${a.parseError}; used low-confidence pattern matching instead.`);
    }
    analyses.push(a);
  }
  const byPath = new Map(analyses.map((a) => [a.path, a]));

  // Model files = files that define a Mongoose model or schema.
  const modelFiles = new Map<string, string[]>();
  for (const a of analyses) {
    if (a.findings.some((f) => f.category === 'Model' || f.category === 'Schema')) modelFiles.set(a.path, a.models);
  }

  // Pass 2: resolve query/operation candidates using cross-file knowledge.
  for (const a of analyses) {
    for (const c of a.candidates) {
      const resolved = resolvesToModel(a, c.rootName, modelFiles, resolver, byPath);
      const confidence = confidenceFor(c, a, resolved);
      if (!confidence) continue;
      a.findings.push({
        file: a.path,
        line: c.line,
        column: c.column,
        category: c.category as Category,
        pattern: `${c.rootText}.${c.methods.slice(0, c.opIndex + 1).map((m) => `${m}()`).join('.')}`,
        evidence: c.evidence,
        confidence,
      });
    }
  }

  // package.json dependency findings.
  const pkgFindings: Finding[] = [];
  const declared = new Set<string>();
  for (const pkg of collected.packageJsons) {
    const r = packageJsonFindings(abs, pkg);
    pkgFindings.push(...r.findings);
    r.deps.forEach((d) => declared.add(d));
  }

  const findings: Finding[] = [...analyses.flatMap((a) => a.findings), ...pkgFindings].sort(
    (x, y) => x.file.localeCompare(y.file) || x.line - y.line || x.column - y.column,
  );
  const findingsByFile = new Map<string, Finding[]>();
  for (const f of findings) {
    if (!findingsByFile.has(f.file)) findingsByFile.set(f.file, []);
    findingsByFile.get(f.file)!.push(f);
  }

  // Agent 1: dependency graph.
  const built = buildGraph(analyses, findingsByFile, modelFiles, resolver, scope);
  warnings.push(...built.warnings);

  const affectedFiles: AffectedFile[] = Array.from(findingsByFile.entries()).map(([file, fs_]) => ({
    file,
    kind: (built.kinds.get(file) ?? 'file') as NodeKind,
    findingCount: fs_.length,
    categories: Array.from(new Set(fs_.map((f) => f.category))),
  }));

  const usesMongoose = declared.has('mongoose') || analyses.some((a) => a.imports.some((i) => i.specifier === 'mongoose' || i.specifier.startsWith('mongoose/')));
  const usesMongodb = declared.has('mongodb') || analyses.some((a) => a.imports.some((i) => i.specifier === 'mongodb' || i.specifier.startsWith('mongodb/')));

  const byCategory: Record<string, number> = {};
  const byConfidence: Record<string, number> = {};
  for (const f of findings) {
    byCategory[f.category] = (byCategory[f.category] ?? 0) + 1;
    byConfidence[f.confidence] = (byConfidence[f.confidence] ?? 0) + 1;
  }
  const modelNames = Array.from(new Set(analyses.flatMap((a) => a.models))).sort();

  const summary: Summary = {
    filesScanned: analyses.length,
    filesWithFindings: affectedFiles.length,
    totalFindings: findings.length,
    byCategory,
    byConfidence,
    modelCount: modelNames.length,
    models: modelNames,
    driver: usesMongoose && usesMongodb ? 'both' : usesMongoose ? 'mongoose' : usesMongodb ? 'mongodb' : 'none',
    parseFailures,
    truncated: collected.truncated,
    nodeCount: generateGraph ? built.graph.nodes.length : 0,
    edgeCount: generateGraph ? built.graph.edges.length : 0,
    durationMs: Date.now() - started,
  };

  return { summary, findings, affectedFiles, graph: generateGraph ? built.graph : null, warnings };
}

#!/usr/bin/env node
// Usage: node dist/cli.js --root <dir> [--scope relevant|all] [--no-graph] [--out file.json] [--pretty]
// Prints the analysis JSON to stdout. Reads source files only; never executes them.

import * as fs from 'fs';
import { analyzeRepository } from './analyze';

function main(): void {
  const args = process.argv.slice(2);
  let root = '';
  let scope: 'relevant' | 'all' = 'relevant';
  let generateGraph = true;
  let out = '';
  let pretty = false;

  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === '--root') root = args[++i] ?? '';
    else if (a === '--scope') {
      const v = args[++i];
      if (v !== 'relevant' && v !== 'all') fail('--scope must be "relevant" or "all"');
      scope = v as 'relevant' | 'all';
    } else if (a === '--no-graph') generateGraph = false;
    else if (a === '--out') out = args[++i] ?? '';
    else if (a === '--pretty') pretty = true;
    else fail(`Unknown argument: ${a}`);
  }
  if (!root) fail('Missing --root <directory>');

  try {
    const result = analyzeRepository(root, { scope, generateGraph });
    const json = JSON.stringify(result, null, pretty ? 2 : undefined);
    if (out) fs.writeFileSync(out, json);
    else process.stdout.write(json);
  } catch (err) {
    fail(err instanceof Error ? err.message : String(err));
  }
}

function fail(message: string): never {
  process.stderr.write(JSON.stringify({ error: message }) + '\n');
  process.exit(1);
}

main();

