describe('scanner', () => {
  it('finds dependencies in package.json and imports', () => {
    expect(at('package.json').map((f) => f.detail ?? f.pattern).join(' ')).toContain('mongoose');
    expect(has('src/models/User.js', 'Dependencies', "require('mongoose')")).toBe(true);
    expect(has('src/models/Post.js', 'Dependencies', "import 'mongoose'")).toBe(true);
    expect(result.summary.driver).toBe('both');
  });

  it('detects connection, schema, model and relationships', () => {
    expect(has('src/config/db.js', 'Connection', 'mongoose.connect()')).toBe(true);
    expect(has('src/models/User.js', 'Schema', 'new Schema()')).toBe(true);
    expect(has('src/models/Post.js', 'Schema', 'new mongoose.Schema()')).toBe(true);
    expect(has('src/models/User.js', 'Model', 'mongoose.model()')).toBe(true);
    expect(has('src/models/User.js', 'Relationships', "ref: 'Post'")).toBe(true);
    expect(has('src/models/Post.js', 'Relationships', "ref: 'User'")).toBe(true);
    expect(result.summary.models).toEqual(['Post', 'User']);
  });

  it('detects queries and operations with high confidence when the model is resolved', () => {
    const q = at('src/services/userService.js');
    expect(q.find((f) => f.pattern === 'User.find()')?.confidence).toBe('high');
    expect(q.some((f) => f.pattern === 'User.findById()')).toBe(true);
    expect(q.some((f) => f.category === 'Relationships' && f.pattern.includes('populate()'))).toBe(true);
    expect(q.find((f) => f.pattern === 'user.save()')?.confidence).toBe('high'); // new User(...)
    expect(q.some((f) => f.category === 'Database operations' && f.pattern === 'User.deleteOne()')).toBe(true);
    expect(has('src/services/postService.js', 'Database operations', 'Post.aggregate()')).toBe(true); // ES import with .js
    expect(has('src/reports/nativeReport.js', 'Connection', 'new MongoClient()')).toBe(true);
    expect(has('src/reports/nativeReport.js', 'Database operations', 'insertOne()')).toBe(true);
    expect(has('src/reports/nativeReport.js', 'Queries', 'find()')).toBe(true);
  });

  it('does not report Array.prototype.find as a MongoDB query', () => {
    expect(at('src/utils/helpers.js')).toHaveLength(0);
  });

  it('keeps unresolvable calls low confidence when the file imports mongoose', () => {
    const a = analyzeFile("const m = require('mongoose');\nfunction f(list){ return list.find(x => x); }", 'x.js');
    expect(a.candidates).toHaveLength(1);
  });

  it('falls back to patterns when a file cannot be parsed', () => {
    const a = analyzeFile("const mongoose = require('mongoose');\nmongoose.connect(uri\n@@@ ((( {{{", 'broken.js');
    const all = analyzeFile('@@@ ((( {{{ mongoose.connect(', 'broken2.js');
    expect(a.findings.length + all.findings.length).toBeGreaterThan(0);
  });
});

describe('Agent 1 dependency graph', () => {
  const g = result.graph!;
  const edge = (s: string, t: string) => g.edges.find((e) => e.source === s && e.target === t);

  it('extracts the real server -> routes -> services -> models chain', () => {
    expect(edge('src/server.js', 'src/routes/userRoutes.js')?.type).toBe('registers_route');
    expect(edge('src/routes/userRoutes.js', 'src/services/userService.js')?.type).toBe('calls_service');
    expect(edge('src/services/userService.js', 'src/models/User.js')?.type).toBe('uses_model');
    expect(edge('src/services/postService.js', 'src/models/Post.js')?.type).toBe('uses_model');
    expect(edge('src/services/postService.js', 'src/services/userService.js')?.type).toBe('calls_service');
    expect(edge('src/server.js', 'src/config/db.js')?.type).toBe('connects_db');
  });

  it('classifies files', () => {
    const kind = (id: string) => g.nodes.find((n) => n.id === id)?.kind;
    expect(kind('src/server.js')).toBe('entry');
    expect(kind('src/routes/userRoutes.js')).toBe('route');
    expect(kind('src/services/userService.js')).toBe('service');
    expect(kind('src/models/User.js')).toBe('model');
    expect(kind('src/config/db.js')).toBe('database');
  });

  it('reports which files are affected if a model changes', () => {
    const affected = g.impact['src/models/User.js'];
    expect(affected).toContain('src/services/userService.js');
    expect(affected).toContain('src/routes/userRoutes.js');
    expect(affected).toContain('src/server.js');
    expect(affected).toContain('src/services/postService.js'); // via userService
  });

  it('omits unrelated files in "relevant" scope but keeps them in "all"', () => {
    expect(g.nodes.some((n) => n.id === 'src/utils/helpers.js')).toBe(false);
    const all = analyzeRepository(sample, { scope: 'all' }).graph!;
    expect(all.nodes.some((n) => n.id === 'src/utils/helpers.js')).toBe(true);
  });

  it('marks impact levels', () => {
    const imp = (id: string) => g.nodes.find((n) => n.id === id)?.impact;
    expect(imp('src/models/User.js')).toBe('direct');
    expect(imp('src/routes/userRoutes.js')).toBe('indirect');
  });
});

