import * as ts from 'typescript';

// Parsing uses the TypeScript Compiler API. Source text is only parsed, never executed.

export type Node = ts.Node;

export interface Parsed {
  sf: ts.SourceFile;
  diagnostics: number; // number of syntax errors the parser recovered from
}

function scriptKind(filename: string): ts.ScriptKind {
  const lower = filename.toLowerCase();
  if (lower.endsWith('.tsx')) return ts.ScriptKind.TSX;
  if (lower.endsWith('.ts') || lower.endsWith('.mts') || lower.endsWith('.cts')) return ts.ScriptKind.TS;
  return ts.ScriptKind.JSX; // .js/.jsx/.mjs/.cjs — JSX is a superset that also accepts plain JS
}

export function parseSource(code: string, filename: string): Parsed {
  const sf = ts.createSourceFile(filename, code, ts.ScriptTarget.Latest, true, scriptKind(filename));
  const diagnostics = ((sf as unknown as { parseDiagnostics?: unknown[] }).parseDiagnostics ?? []).length;
  return { sf, diagnostics };
}

export function walk(root: Node, visit: (n: Node, parent: Node | undefined) => void): void {
  const go = (n: Node, parent: Node | undefined): void => {
    visit(n, parent);
    ts.forEachChild(n, (c) => go(c, n));
  };
  go(root, undefined);
}

export function strValue(n: Node | undefined | null): string | null {
  if (!n) return null;
  if (ts.isStringLiteral(n) || ts.isNoSubstitutionTemplateLiteral(n)) return n.text;
  return null;
}

/** Strip parentheses, await, `as` casts and non-null assertions. */
export function unwrap(n: Node | undefined | null): Node | null {
  let cur: Node | null = n ?? null;
  while (
    cur &&
    (ts.isParenthesizedExpression(cur) ||
      ts.isAwaitExpression(cur) ||
      ts.isAsExpression(cur) ||
      ts.isNonNullExpression(cur) ||
      ts.isTypeAssertionExpression(cur) ||
      ts.isSatisfiesExpression(cur))
  ) {
    cur = cur.expression;
  }
  return cur;
}

export type Access = ts.PropertyAccessExpression | ts.ElementAccessExpression;

export function isAccess(n: Node | undefined | null): n is Access {
  return !!n && (ts.isPropertyAccessExpression(n) || ts.isElementAccessExpression(n));
}

export function accessName(n: Node): string | null {
  if (ts.isPropertyAccessExpression(n)) return n.name.text;
  if (ts.isElementAccessExpression(n) && ts.isStringLiteralLike(n.argumentExpression)) return n.argumentExpression.text;
  return null;
}

export interface ChainMethod {
  name: string;
  call: ts.CallExpression;
  nameNode: Node; // the property-name token, used for accurate line numbers
}

export interface ChainInfo {
  root: Node | null;
  methods: ChainMethod[]; // called methods, root -> outermost
}

/** Unwind `a.b().c().d()` style chains down to the root expression. */
export function analyzeChain(expr: Node): ChainInfo {
  const methods: ChainMethod[] = [];
  let cur: Node | null = expr;
  for (let i = 0; i < 300 && cur; i++) {
    cur = unwrap(cur);
    if (!cur) break;
    if (ts.isCallExpression(cur)) {
      const callee: ts.Expression = cur.expression;
      if (isAccess(callee)) {
        const name = accessName(callee);
        if (name) {
          methods.unshift({ name, call: cur, nameNode: ts.isPropertyAccessExpression(callee) ? callee.name : callee.argumentExpression });
        }
      }
      cur = callee;
    } else if (isAccess(cur)) {
      cur = cur.expression;
    } else {
      break;
    }
  }
  return { root: cur, methods };
}

import * as fs from 'fs';
import * as path from 'path';
import * as ts from 'typescript';
import { Node, accessName, isAccess, strValue, walk } from './ast';
import { Binding, ImportRef } from './types';

export interface ExtractedImports {
  imports: ImportRef[];
  bindings: Binding[];
  dynamicCount: number;
}

/** Source specifier of `require('x')` or `await import('x')`, else null. */
function requireSource(node: Node | undefined | null): string | null {
  if (!node) return null;
  let n: Node = node;
  if (ts.isAwaitExpression(n)) n = n.expression;
  if (!ts.isCallExpression(n) || n.arguments.length < 1) return null;
  const callee = n.expression;
  if (ts.isIdentifier(callee) && callee.text === 'require') return strValue(n.arguments[0]);
  if (callee.kind === ts.SyntaxKind.ImportKeyword) return strValue(n.arguments[0]);
  return null;
}

export function extractImports(sf: ts.SourceFile): ExtractedImports {
  const imports: ImportRef[] = [];
  const bindings: Binding[] = [];
  let dynamicCount = 0;

  const pos = (n: Node) => {
    const p = sf.getLineAndCharacterOfPosition(n.getStart(sf));
    return { line: p.line + 1, column: p.character + 1 };
  };

  walk(sf, (n) => {
    if (ts.isImportDeclaration(n) && ts.isStringLiteral(n.moduleSpecifier)) {
      const source = n.moduleSpecifier.text;
      const p = pos(n);
      imports.push({ specifier: source, kind: 'import', ...p });
      const clause = n.importClause;
      if (clause) {
        if (clause.name) bindings.push({ local: clause.name.text, source, imported: 'default', line: p.line });
        const nb = clause.namedBindings;
        if (nb && ts.isNamespaceImport(nb)) bindings.push({ local: nb.name.text, source, imported: '*', line: p.line });
        else if (nb && ts.isNamedImports(nb)) {
          for (const el of nb.elements) {
            bindings.push({ local: el.name.text, source, imported: (el.propertyName ?? el.name).text, line: p.line });
          }
        }
      }
    } else if (ts.isExportDeclaration(n) && n.moduleSpecifier && ts.isStringLiteral(n.moduleSpecifier)) {
      imports.push({ specifier: n.moduleSpecifier.text, kind: 'export-from', ...pos(n) });
    } else if (ts.isImportEqualsDeclaration(n) && ts.isExternalModuleReference(n.moduleReference)) {
      const source = strValue(n.moduleReference.expression);
      if (source) {
        const p = pos(n);
        imports.push({ specifier: source, kind: 'require', ...p });
        bindings.push({ local: n.name.text, source, imported: 'default', line: p.line });
      }
    } else if (ts.isVariableDeclaration(n) && n.initializer) {
      const line = pos(n).line;
      const direct = requireSource(n.initializer);
      if (direct !== null) {
        if (ts.isIdentifier(n.name)) {
          bindings.push({ local: n.name.text, source: direct, imported: 'default', line });
        } else if (ts.isObjectBindingPattern(n.name)) {
          for (const el of n.name.elements) {
            if (el.dotDotDotToken || !ts.isIdentifier(el.name)) continue;
            const imported = el.propertyName && ts.isIdentifier(el.propertyName) ? el.propertyName.text : el.name.text;
            bindings.push({ local: el.name.text, source: direct, imported, line });
          }
        }
      } else if (isAccess(n.initializer) && ts.isIdentifier(n.name)) {
        const inner = requireSource(n.initializer.expression);
        const prop = accessName(n.initializer);
        if (inner !== null && prop) bindings.push({ local: n.name.text, source: inner, imported: prop, line });
      }
    } else if (ts.isCallExpression(n)) {
      const callee = n.expression;
      if (ts.isIdentifier(callee) && callee.text === 'require' && n.arguments.length >= 1) {
        const spec = strValue(n.arguments[0]);
        if (spec) imports.push({ specifier: spec, kind: 'require', ...pos(n) });
      } else if (callee.kind === ts.SyntaxKind.ImportKeyword) {
        const spec = strValue(n.arguments[0]);
        if (spec) imports.push({ specifier: spec, kind: 'dynamic', ...pos(n) });
        else dynamicCount++;
      }
    }
  });

  return { imports, bindings, dynamicCount };
}

// ---------- path resolution ----------

const EXTS = ['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs'];

export interface Resolver {
  /** Resolve an import specifier from a repo-relative file to another repo-relative file, or null. */
  resolve(from: string, specifier: string): string | null;
}

interface AliasRule {
  prefix: string;
  suffix: string;
  hasWildcard: boolean;
  targets: string[];
}

function readJsonLoose(file: string): Record<string, unknown> | null {
  try {
    const text = fs
      .readFileSync(file, 'utf8')
      .replace(/^﻿/, '')
      .replace(/\/\*[\s\S]*?\*\//g, '')
      .replace(/^\s*\/\/.*$/gm, '')
      .replace(/,\s*([}\]])/g, '$1');
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function loadAliases(root: string): { baseUrl: string | null; rules: AliasRule[] } {
  for (const name of ['tsconfig.json', 'jsconfig.json']) {
    const cfg = readJsonLoose(path.join(root, name));
    const opts = cfg && (cfg.compilerOptions as Record<string, unknown> | undefined);
    if (!opts) continue;
    const baseUrl = typeof opts.baseUrl === 'string' ? path.posix.normalize(opts.baseUrl.replace(/\\/g, '/')) : null;
    const rules: AliasRule[] = [];
    const paths = opts.paths as Record<string, string[]> | undefined;
    if (paths && typeof paths === 'object') {
      for (const [pattern, targets] of Object.entries(paths)) {
        if (!Array.isArray(targets)) continue;
        const star = pattern.indexOf('*');
        rules.push({
          prefix: star === -1 ? pattern : pattern.slice(0, star),
          suffix: star === -1 ? '' : pattern.slice(star + 1),
          hasWildcard: star !== -1,
          targets,
        });
      }
    }
    if (baseUrl !== null || rules.length) return { baseUrl, rules };
  }
  return { baseUrl: null, rules: [] };
}

export function createResolver(root: string, files: Set<string>): Resolver {
  const aliases = loadAliases(root);

  const tryResolve = (basePath: string): string | null => {
    const base = path.posix.normalize(basePath);
    if (base.startsWith('..') || base.startsWith('/')) return null;
    const candidates = [base, ...EXTS.map((e) => base + e), ...EXTS.map((e) => `${base}/index${e}`)];
    // TypeScript ESM style: import './x.js' that actually refers to x.ts
    const m = base.match(/^(.*)\.(m|c)?jsx?$/);
    if (m) candidates.push(`${m[1]}.ts`, `${m[1]}.tsx`);
    for (const c of candidates) if (files.has(c)) return c;
    return null;
  };

  return {
    resolve(from: string, specifier: string): string | null {
      if (specifier.startsWith('.')) {
        return tryResolve(path.posix.join(path.posix.dirname(from), specifier));
      }
      for (const rule of aliases.rules) {
        if (!specifier.startsWith(rule.prefix) || !specifier.endsWith(rule.suffix)) continue;
        if (!rule.hasWildcard && specifier !== rule.prefix) continue;
        const star = specifier.slice(rule.prefix.length, specifier.length - rule.suffix.length);
        for (const target of rule.targets) {
          const mapped = rule.hasWildcard ? target.replace('*', star) : target;
          const hit = tryResolve(path.posix.join(aliases.baseUrl ?? '.', mapped));
          if (hit) return hit;
        }
      }
      if (aliases.baseUrl !== null) {
        const hit = tryResolve(path.posix.join(aliases.baseUrl, specifier));
        if (hit) return hit;
      }
      return null; // external package or unresolved alias
    },
  };
}

import * as fs from 'fs';
import * as path from 'path';
import * as ts from 'typescript';
import { Node, accessName, analyzeChain, isAccess, parseSource, strValue, unwrap, walk } from './ast';
import { extractImports } from './dependencies';
import {
  DB_OP_METHODS,
  FALLBACK_PATTERNS,
  GENERATED_PATTERNS,
  LIMITS,
  QUERY_METHODS,
  ROUTE_METHODS,
  SKIP_DIRS,
  SOURCE_EXTS,
} from './rules';
import { CallCandidate, Category, Confidence, FileAnalysis, Finding } from './types';

// ---------------------------------------------------------------------------
// Step 2 — collect source files (never executes anything from the repository)
// ---------------------------------------------------------------------------

export interface CollectResult {
  files: string[];
  packageJsons: string[];
  warnings: string[];
  truncated: boolean;
}

export function collectFiles(root: string, limits = LIMITS): CollectResult {
  const files: string[] = [];
  const packageJsons: string[] = [];
  const warnings: string[] = [];
  let truncated = false;
  let totalBytes = 0;
  const deadline = Date.now() + limits.timeMs;
  const stack: string[] = [''];

  outer: while (stack.length) {
    const rel = stack.pop() as string;
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(path.join(root, rel), { withFileTypes: true });
    } catch {
      warnings.push(`Could not read directory ${rel || '.'}`);
      continue;
    }
    for (const e of entries) {
      if (Date.now() > deadline) {
        truncated = true;
        warnings.push('Time limit reached; analysis is partial.');
        break outer;
      }
      if (e.isSymbolicLink()) continue; // never follow symlinks out of the repo
      const childRel = rel ? `${rel}/${e.name}` : e.name;
      if (e.isDirectory()) {
        if (SKIP_DIRS.has(e.name) || e.name.startsWith('.')) continue;
        stack.push(childRel);
        continue;
      }
      if (!e.isFile()) continue;
      if (e.name === 'package.json') {
        packageJsons.push(childRel);
        continue;
      }
      if (!SOURCE_EXTS.has(path.extname(e.name).toLowerCase())) continue;
      if (GENERATED_PATTERNS.some((r) => r.test(e.name))) continue;
      let size = 0;
      try {
        size = fs.statSync(path.join(root, childRel)).size;
      } catch {
        continue;
      }
      if (size > limits.maxFileBytes) {
        warnings.push(`Skipped large file ${childRel}`);
        continue;
      }
      if (files.length >= limits.maxFiles || totalBytes + size > limits.maxTotalBytes) {
        truncated = true;
        warnings.push('File limit reached; analysis is partial.');
        break outer;
      }
      files.push(childRel);
      totalBytes += size;
    }
  }

  files.sort();
  packageJsons.sort();
  return { files, packageJsons, warnings, truncated };
}

// ---------------------------------------------------------------------------
// Step 3 — detect MongoDB usage (pattern evidence + AST context)
// ---------------------------------------------------------------------------

const isPkg = (spec: string, name: string) => spec === name || spec.startsWith(`${name}/`);

function categoryOf(method: string): CallCandidate['category'] | null {
  if (QUERY_METHODS.has(method)) return 'Queries';
  if (DB_OP_METHODS.has(method)) return 'Database operations';
  if (method === 'populate') return 'Relationships';
  return null;
}

function emptyAnalysis(rel: string): FileAnalysis {
  return {
    path: rel,
    imports: [],
    bindings: [],
    findings: [],
    candidates: [],
    registrations: [],
    localModels: {},
    docVars: {},
    flags: { listen: false, expressCall: false, routerCall: false, routeCalls: 0 },
    usesMongoLib: false,
    models: [],
    dynamicImports: 0,
  };
}

export function analyzeFile(code: string, rel: string): FileAnalysis {
  const text = code.replace(/^﻿/, '');
  const lines = text.split(/\r?\n/);
  let result = emptyAnalysis(rel);
  const { sf, diagnostics } = parseSource(text, rel);
  try {
    astPass(sf, result, lines);
  } catch (err) {
    // e.g. stack overflow on pathologically deep code: discard partial state, use patterns only
    result = emptyAnalysis(rel);
    result.parseError = `analysis failed (${err instanceof Error ? err.message : 'unknown error'})`;
    fallbackScan(lines, result);
    return result;
  }
  if (diagnostics > 0) {
    result.parseError = `${diagnostics} syntax error(s); results for this file may be incomplete`;
    if (result.findings.length === 0 && result.imports.length === 0) fallbackScan(lines, result);
  }
  return result;
}

function fallbackScan(lines: string[], a: FileAnalysis): void {
  lines.forEach((text, i) => {
    for (const rule of FALLBACK_PATTERNS) {
      if (rule.regex.test(text)) {
        a.findings.push({
          file: a.path,
          line: i + 1,
          column: 1,
          category: rule.category as Category,
          pattern: rule.pattern,
          evidence: text.trim().slice(0, 160),
          confidence: 'low',
        });
        if (rule.category === 'Dependencies' || rule.category === 'Connection') a.usesMongoLib = true;
      }
    }
    // Minimal import extraction so the graph still has edges for unparsable files.
    const re = /(?:require\(\s*|from\s+)['"](\.{1,2}\/[^'"]+)['"]/g;
    let m: RegExpExecArray | null;
    while ((m = re.exec(text))) a.imports.push({ specifier: m[1], kind: 'import', line: i + 1, column: m.index + 1 });
  });
}

function astPass(sf: ts.SourceFile, a: FileAnalysis, lines: string[]): void {
  const ev = (line: number) => (lines[line - 1] ?? '').trim().slice(0, 160);
  const loc = (n: Node) => {
    const p = sf.getLineAndCharacterOfPosition(n.getStart(sf));
    return { line: p.line + 1, column: p.character + 1 };
  };
  const add = (category: Category, pattern: string, n: Node, confidence: Confidence, detail?: string) => {
    const { line, column } = loc(n);
    a.findings.push({ file: a.path, line, column, category, pattern, evidence: ev(line), confidence, detail });
  };

  const { imports, bindings, dynamicCount } = extractImports(sf);
  a.imports = imports;
  a.bindings = bindings;
  a.dynamicImports = dynamicCount;

  const mongooseNs = new Set<string>();
  const mongodbNs = new Set<string>();
  const mongooseNamed = new Map<string, string>(); // local -> exported name
  const mongodbNamed = new Map<string, string>();
  for (const b of bindings) {
    if (isPkg(b.source, 'mongoose')) {
      if (b.imported === 'default' || b.imported === '*') mongooseNs.add(b.local);
      else mongooseNamed.set(b.local, b.imported);
    } else if (isPkg(b.source, 'mongodb')) {
      if (b.imported === 'default' || b.imported === '*') mongodbNs.add(b.local);
      else mongodbNamed.set(b.local, b.imported);
    }
  }
  a.usesMongoLib = imports.some((i) => isPkg(i.specifier, 'mongoose') || isPkg(i.specifier, 'mongodb'));

  // Dependencies: import / require of the packages.
  for (const imp of imports) {
    if (isPkg(imp.specifier, 'mongoose') || isPkg(imp.specifier, 'mongodb')) {
      a.findings.push({
        file: a.path,
        line: imp.line,
        column: imp.column,
        category: 'Dependencies',
        pattern: imp.kind === 'require' ? `require('${imp.specifier}')` : `import '${imp.specifier}'`,
        evidence: ev(imp.line),
        confidence: 'high',
        detail: imp.specifier,
      });
    }
  }

  const connVars = new Set<string>();
  const localModels = new Map<string, string>();
  const docVars = new Map<string, string>();
  const refs: { node: Node; target: string }[] = [];
  const seenCandidates = new Set<string>();

  const idText = (n: Node | undefined | null): string | null => (n && ts.isIdentifier(n) ? n.text : null);

  const isConnectionFactory = (call: ts.CallExpression): boolean => {
    const c = call.expression;
    if (isAccess(c) && ts.isIdentifier(c.expression)) {
      return mongooseNs.has(c.expression.text) && accessName(c) === 'createConnection';
    }
    return ts.isIdentifier(c) && mongooseNamed.get(c.text) === 'createConnection';
  };

  const modelCall = (call: ts.CallExpression): { conf: Confidence; name: string } | null => {
    const callee = call.expression;
    const first = strValue(call.arguments[0]);
    if (isAccess(callee) && accessName(callee) === 'model' && ts.isIdentifier(callee.expression)) {
      const o = callee.expression.text;
      if (mongooseNs.has(o) || connVars.has(o)) return { conf: 'high', name: first ?? 'unknown' };
      if (a.usesMongoLib && first !== null && call.arguments.length >= 2) return { conf: 'medium', name: first };
    } else if (ts.isIdentifier(callee) && mongooseNamed.get(callee.text) === 'model') {
      return { conf: 'high', name: first ?? 'unknown' };
    }
    return null;
  };

  const findModelCallIn = (n: Node | undefined | null): ts.CallExpression | null => {
    const cur = unwrap(n);
    if (!cur) return null;
    if (ts.isCallExpression(cur) && modelCall(cur)) return cur;
    if (ts.isBinaryExpression(cur)) return findModelCallIn(cur.left) ?? findModelCallIn(cur.right);
    if (ts.isConditionalExpression(cur)) return findModelCallIn(cur.whenTrue) ?? findModelCallIn(cur.whenFalse);
    return null;
  };

  const argRoot = (arg: Node): { binding: string | null; specifier: string | null } => {
    const x = unwrap(arg);
    if (!x) return { binding: null, specifier: null };
    if (ts.isIdentifier(x)) return { binding: x.text, specifier: null };
    if (isAccess(x)) {
      const r = idText(analyzeChain(x).root);
      if (r) return { binding: r, specifier: null };
    }
    if (ts.isCallExpression(x) && ts.isIdentifier(x.expression)) {
      if (x.expression.text === 'require') return { binding: null, specifier: strValue(x.arguments[0]) };
      return { binding: x.expression.text, specifier: null };
    }
    return { binding: null, specifier: null };
  };

  const onVariable = (n: ts.VariableDeclaration): void => {
    const init = n.initializer;
    if (!init) return;
    const target = n.name;
    if (ts.isIdentifier(init) && mongooseNs.has(init.text) && ts.isObjectBindingPattern(target)) {
      for (const el of target.elements) {
        if (el.dotDotDotToken || !ts.isIdentifier(el.name)) continue;
        const imported = el.propertyName && ts.isIdentifier(el.propertyName) ? el.propertyName.text : el.name.text;
        mongooseNamed.set(el.name.text, imported);
      }
    }
    if (isAccess(init) && ts.isIdentifier(init.expression) && mongooseNs.has(init.expression.text) && ts.isIdentifier(target)) {
      const prop = accessName(init);
      if (prop === 'connection') connVars.add(target.text);
      else if (prop) mongooseNamed.set(target.text, prop);
    }
    if (!ts.isIdentifier(target)) return;
    const inner = unwrap(init);
    if (inner && ts.isCallExpression(inner) && isConnectionFactory(inner)) connVars.add(target.text);
    const mc = findModelCallIn(init);
    if (mc) {
      const info = modelCall(mc);
      if (info) localModels.set(target.text, info.name);
    }
    if (inner && ts.isNewExpression(inner) && ts.isIdentifier(inner.expression)) {
      docVars.set(target.text, inner.expression.text); // const user = new User(...)
    } else if (inner) {
      const chain = analyzeChain(inner);
      const root = idText(chain.root);
      if (root && chain.methods.some((m) => QUERY_METHODS.has(m.name) && m.name !== 'save')) {
        docVars.set(target.text, root); // const user = await User.findById(...)
      }
    }
  };

  const onNew = (n: ts.NewExpression): void => {
    const c = n.expression;
    if (ts.isIdentifier(c)) {
      if (mongooseNamed.get(c.text) === 'Schema') add('Schema', 'new Schema()', n, 'high');
      else if (mongodbNamed.get(c.text) === 'MongoClient') add('Connection', 'new MongoClient()', n, 'high');
    } else if (isAccess(c) && ts.isIdentifier(c.expression)) {
      const o = c.expression.text;
      const prop = accessName(c);
      if (mongooseNs.has(o) && prop === 'Schema') add('Schema', `new ${o}.Schema()`, n, 'high');
      else if (mongodbNs.has(o) && prop === 'MongoClient') add('Connection', `new ${o}.MongoClient()`, n, 'high');
    }
  };

  const onCall = (n: ts.CallExpression, parent: Node | undefined): void => {
    const callee = n.expression;

    // --- connection / model detection ---
    if (isAccess(callee) && ts.isIdentifier(callee.expression)) {
      const obj = callee.expression.text;
      const prop = accessName(callee);
      if (mongooseNs.has(obj) && (prop === 'connect' || prop === 'createConnection')) {
        add('Connection', `${obj}.${prop}()`, n, 'high');
      } else if (mongodbNamed.get(obj) === 'MongoClient' && prop === 'connect') {
        add('Connection', `${obj}.connect()`, n, 'high');
      }
      const mc = modelCall(n);
      if (mc) {
        add('Model', `${obj}.model()`, n, mc.conf, mc.name);
        a.models.push(mc.name);
      }
    } else if (ts.isIdentifier(callee)) {
      const named = mongooseNamed.get(callee.text);
      if (named === 'connect' || named === 'createConnection') add('Connection', `${callee.text}()`, n, 'high');
      const mc = modelCall(n);
      if (mc) {
        add('Model', `${callee.text}()`, n, mc.conf, mc.name);
        a.models.push(mc.name);
      }
      if (callee.text === 'express') a.flags.expressCall = true;
      if (callee.text === 'Router') a.flags.routerCall = true;
    }

    // --- route / server structure (used to classify files and label edges) ---
    if (isAccess(callee)) {
      const prop = accessName(callee);
      if (prop === 'Router') a.flags.routerCall = true;
      if (prop === 'listen' && n.arguments.length >= 1) a.flags.listen = true;
      const line = loc(n).line;
      if (prop === 'use' && n.arguments.length >= 1) {
        const first = strValue(n.arguments[0]);
        for (const arg of n.arguments) {
          const r = argRoot(arg);
          if (r.binding || r.specifier) a.registrations.push({ kind: 'use', binding: r.binding, specifier: r.specifier, path: first, method: 'USE', line });
        }
      } else if (prop && ROUTE_METHODS.has(prop) && n.arguments.length >= 2) {
        const p = strValue(n.arguments[0]);
        if (p !== null && p.startsWith('/')) {
          a.flags.routeCalls++;
          for (const arg of n.arguments.slice(1)) {
            const r = argRoot(arg);
            if (r.binding || r.specifier) {
              a.registrations.push({ kind: 'handler', binding: r.binding, specifier: r.specifier, path: p, method: prop.toUpperCase(), line });
            }
          }
        }
      }
    }

    // --- query / operation / relationship candidates (outermost call of each chain) ---
    if (parent && isAccess(parent) && parent.expression === n) return;
    const chain = analyzeChain(n);
    const names = chain.methods.map((m) => m.name);
    chain.methods.forEach((m, idx) => {
      const category = categoryOf(m.name);
      if (!category) return;
      const { line, column } = loc(m.nameNode);
      const key = `${line}:${column}:${m.name}`;
      if (seenCandidates.has(key)) return;
      seenCandidates.add(key);
      const rootName = idText(chain.root);
      const rootText = rootName ?? (chain.root?.kind === ts.SyntaxKind.ThisKeyword ? 'this' : '(expr)');
      a.candidates.push({
        rootName,
        rootText,
        methods: names,
        opIndex: idx,
        op: m.name,
        category,
        line,
        column,
        evidence: ev(line),
        hints: names,
        viaModelCall: !!rootName && mongooseNs.has(rootName) && names.slice(0, idx).includes('model'),
      });
    });
  };

  walk(sf, (n, parent) => {
    if (ts.isVariableDeclaration(n)) onVariable(n);
    else if (ts.isPropertyAssignment(n)) {
      const key = ts.isIdentifier(n.name) || ts.isStringLiteral(n.name) ? n.name.text : null;
      const target = strValue(n.initializer);
      if (key === 'ref' && target) refs.push({ node: n, target });
    } else if (ts.isNewExpression(n)) onNew(n);
    else if (ts.isCallExpression(n)) onCall(n, parent);
  });

  // Relationships declared in schemas (`ref: 'User'`).
  const hasSchema = a.findings.some((f) => f.category === 'Schema');
  if (hasSchema || a.usesMongoLib) {
    for (const r of refs) add('Relationships', `ref: '${r.target}'`, r.node, hasSchema ? 'high' : 'medium', r.target);
  }

  a.localModels = Object.fromEntries(localModels);
  a.docVars = Object.fromEntries(docVars);
  a.models = Array.from(new Set(a.models));
}

import assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { describe, it } from 'node:test';
import { analyzeRepository } from '../analyze';
import { analyzeFile } from '../scanner';

// dist/__tests__ -> analyzer -> migrateai
const sample = path.resolve(__dirname, '../../../tests/fixtures/sample-app');
const result = analyzeRepository(sample);
const at = (file: string) => result.findings.filter((f) => f.file === file);
const has = (file: string, category: string, pattern: string) =>
  at(file).some((f) => f.category === category && f.pattern.includes(pattern));

describe('scanner', () => {
  it('finds dependencies in package.json and imports', () => {
    assert.ok(at('package.json').some((f) => f.pattern.endsWith('.mongoose')));
    assert.ok(at('package.json').some((f) => f.pattern.endsWith('.mongodb')));
    assert.ok(has('src/models/User.js', 'Dependencies', "require('mongoose')"));
    assert.ok(has('src/models/Post.js', 'Dependencies', "import 'mongoose'"));
    assert.equal(result.summary.driver, 'both');
  });

  it('detects connection, schema, model and relationships', () => {
    assert.ok(has('src/config/db.js', 'Connection', 'mongoose.connect()'));
    assert.ok(has('src/models/User.js', 'Schema', 'new Schema()'));
    assert.ok(has('src/models/Post.js', 'Schema', 'new mongoose.Schema()'));
    assert.ok(has('src/models/User.js', 'Model', 'mongoose.model()'));
    assert.ok(has('src/models/User.js', 'Relationships', "ref: 'Post'"));
    assert.ok(has('src/models/Post.js', 'Relationships', "ref: 'User'"));
    assert.deepEqual(result.summary.models, ['Post', 'User']);
  });

  it('detects queries and operations with high confidence when the model is resolved', () => {
    const q = at('src/services/userService.js');
    assert.equal(q.find((f) => f.pattern === 'User.find()')?.confidence, 'high');
    assert.ok(q.some((f) => f.pattern === 'User.findById()'));
    assert.ok(q.some((f) => f.category === 'Relationships' && f.pattern.includes('populate()')));
    assert.equal(q.find((f) => f.pattern === 'user.save()')?.confidence, 'high'); // const user = new User(...)
    assert.ok(q.some((f) => f.category === 'Database operations' && f.pattern === 'User.deleteOne()'));
    assert.ok(has('src/services/postService.js', 'Database operations', 'Post.aggregate()')); // ES import ending in .js
    assert.ok(has('src/reports/nativeReport.js', 'Connection', 'new MongoClient()'));
    assert.ok(has('src/reports/nativeReport.js', 'Database operations', 'insertOne()'));
    assert.ok(has('src/reports/nativeReport.js', 'Queries', 'find()'));
  });

  it('reports the line of the method, not the start of a multi-line chain', () => {
    const f = at('src/services/userService.js').find((x) => x.pattern === 'User.findById().populate()');
    assert.ok(f);
    assert.equal(f.evidence.includes('populate'), true);
  });

  it('does not report Array.prototype.find as a MongoDB query', () => {
    assert.equal(at('src/utils/helpers.js').length, 0);
  });

  it('keeps unresolvable calls low confidence when the file imports mongoose', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'migrateai-test-'));
    try {
      fs.writeFileSync(path.join(dir, 'x.js'), "const m = require('mongoose');\nfunction f(list){ return list.find(x => x); }\n");
      fs.writeFileSync(path.join(dir, 'y.js'), 'function g(list){ return list.find(x => x); }\n');
      const r = analyzeRepository(dir);
      const q = r.findings.filter((f) => f.category === 'Queries');
      assert.equal(q.length, 1);
      assert.equal(q[0].file, 'x.js');
      assert.equal(q[0].confidence, 'low');
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });

  it('falls back to patterns when a file is badly broken', () => {
    const a = analyzeFile('@@@ ((( {{{ mongoose.connect(', 'broken.js');
    assert.ok(a.parseError);
    assert.ok(a.findings.some((f) => f.category === 'Connection' && f.confidence === 'low'));
  });

  it('handles TypeScript files', () => {
    const a = analyzeFile(
      "import mongoose, { Schema, Document } from 'mongoose';\ninterface IU extends Document { name: string }\nconst s = new Schema<IU>({ name: String });\nexport const U = mongoose.model<IU>('U', s);\n",
      'u.ts',
    );
    assert.ok(a.findings.some((f) => f.category === 'Schema'));
    assert.ok(a.findings.some((f) => f.category === 'Model' && f.detail === 'U'));
  });
});

describe('Agent 1 dependency graph', () => {
  const g = result.graph!;
  const edge = (s: string, t: string) => g.edges.find((e) => e.source === s && e.target === t);

  it('extracts the real server -> routes -> services -> models chain', () => {
    assert.equal(edge('src/server.js', 'src/routes/userRoutes.js')?.type, 'registers_route');
    assert.equal(edge('src/routes/userRoutes.js', 'src/services/userService.js')?.type, 'calls_service');
    assert.equal(edge('src/services/userService.js', 'src/models/User.js')?.type, 'uses_model');
    assert.equal(edge('src/services/postService.js', 'src/models/Post.js')?.type, 'uses_model');
    assert.equal(edge('src/services/postService.js', 'src/services/userService.js')?.type, 'calls_service');
    assert.equal(edge('src/server.js', 'src/config/db.js')?.type, 'connects_db');
  });

  it('labels edges with real route paths and model names', () => {
    assert.equal(edge('src/server.js', 'src/routes/userRoutes.js')?.label, '/users');
    assert.equal(edge('src/services/userService.js', 'src/models/User.js')?.label, 'User');
  });

  it('classifies files', () => {
    const kind = (id: string) => g.nodes.find((n) => n.id === id)?.kind;
    assert.equal(kind('src/server.js'), 'entry');
    assert.equal(kind('src/routes/userRoutes.js'), 'route');
    assert.equal(kind('src/services/userService.js'), 'service');
    assert.equal(kind('src/models/User.js'), 'model');
    assert.equal(kind('src/config/db.js'), 'database');
  });

  it('reports which files are affected if a model changes', () => {
    const affected = g.impact['src/models/User.js'];
    assert.ok(affected.includes('src/services/userService.js'));
    assert.ok(affected.includes('src/routes/userRoutes.js'));
    assert.ok(affected.includes('src/server.js'));
    assert.ok(affected.includes('src/services/postService.js')); // via userService
  });

  it('omits unrelated files in "relevant" scope but keeps them in "all"', () => {
    assert.equal(g.nodes.some((n) => n.id === 'src/utils/helpers.js'), false);
    const all = analyzeRepository(sample, { scope: 'all' }).graph!;
    assert.equal(all.nodes.some((n) => n.id === 'src/utils/helpers.js'), true);
  });

  it('marks impact levels', () => {
    const imp = (id: string) => g.nodes.find((n) => n.id === id)?.impact;
    assert.equal(imp('src/models/User.js'), 'direct');
    assert.equal(imp('src/routes/userRoutes.js'), 'indirect');
  });

  it('survives import cycles', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'migrateai-cycle-'));
    try {
      fs.writeFileSync(path.join(dir, 'a.js'), "const b = require('./b');\nconst mongoose = require('mongoose');\nmodule.exports = mongoose.model('A', new mongoose.Schema({}));\n");
      fs.writeFileSync(path.join(dir, 'b.js'), "const a = require('./a');\nmodule.exports = a;\n");
      const r = analyzeRepository(dir);
      assert.equal(r.graph!.nodes.length, 2);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
});

