const PAGE = 200;

export default function FindingsTable({ findings, onOpenFile }: Props) {
  const [category, setCategory] = useState<Category | 'all'>('all');
  const [confidence, setConfidence] = useState<Confidence | 'all'>('all');
  const [query, setQuery] = useState('');
  const [limit, setLimit] = useState(PAGE);

  const counts = useMemo(() => {
    const c: Record<string, number> = {};
    for (const f of findings) c[f.category] = (c[f.category] ?? 0) + 1;
    return c;
  }, [findings]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return findings.filter(
      (f) =>
        (category === 'all' || f.category === category) &&
        (confidence === 'all' || f.confidence === confidence) &&
        (!q || f.file.toLowerCase().includes(q) || f.pattern.toLowerCase().includes(q) || f.evidence.toLowerCase().includes(q)),
    );
  }, [findings, category, confidence, query]);

  return (
    <div className="rounded-xl border border-ink-600 bg-ink-900/80">
      <div className="flex flex-wrap items-center gap-2 border-b border-ink-700 p-3">
        <Chip active={category === 'all'} onClick={() => setCategory('all')}>
          All · {findings.length}
        </Chip>
        {CATEGORIES.filter((c) => counts[c]).map((c) => (
          <Chip key={c} active={category === c} onClick={() => setCategory(c)}>
            {c} · {counts[c]}
          </Chip>
        ))}
        <div className="ml-auto flex items-center gap-2">
          <select
            value={confidence}
            onChange={(e) => setConfidence(e.target.value as Confidence | 'all')}
            className="rounded-md border border-ink-600 bg-ink-950 px-2 py-1 text-xs text-zinc-200 focus:border-violet focus:outline-none"
            aria-label="Filter by confidence"
          >
            <option value="all">Any confidence</option>
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search file, pattern, code…"
            className="w-56 rounded-md border border-ink-600 bg-ink-950 px-2.5 py-1 text-xs text-zinc-100 placeholder:text-zinc-600 focus:border-violet focus:outline-none"
          />
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left text-xs">
          <thead className="text-[11px] uppercase tracking-wide text-zinc-500">
            <tr>
              <th className="px-3 py-2 font-medium">Location</th>
              <th className="px-3 py-2 font-medium">Category</th>
              <th className="px-3 py-2 font-medium">Pattern</th>
              <th className="px-3 py-2 font-medium">Confidence</th>
              <th className="px-3 py-2 font-medium">Evidence</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-ink-700/70">
            {filtered.slice(0, limit).map((f, i) => (
              <tr key={`${f.file}:${f.line}:${f.column}:${f.pattern}:${i}`} className="hover:bg-ink-800/70">
                <td className="whitespace-nowrap px-3 py-2 font-mono">
                  <button onClick={() => onOpenFile(f.file)} className="text-violet-soft hover:underline" title="Show in dependency graph">
                    {f.file}
                  </button>
                  <span className="text-zinc-500">:{f.line}</span>
                </td>
                <td className="px-3 py-2">
                  <span className={`rounded border px-1.5 py-0.5 ${CATEGORY_CLASS[f.category]}`}>{f.category}</span>
                </td>
                <td className="whitespace-nowrap px-3 py-2 font-mono text-zinc-200">{f.pattern}</td>
                <td className={`px-3 py-2 ${CONFIDENCE_CLASS[f.confidence]}`}>{f.confidence}</td>
                <td className="max-w-md truncate px-3 py-2 font-mono text-zinc-500" title={f.evidence}>
                  {f.evidence}
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={5} className="px-3 py-8 text-center text-zinc-500">
                  No findings match these filters.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {filtered.length > limit && (
        <div className="border-t border-ink-700 p-3 text-center">
          <button onClick={() => setLimit((l) => l + PAGE)} className="text-xs text-violet-soft hover:underline">
            Show more ({filtered.length - limit} remaining)
          </button>
        </div>
      )}
    </div>
  );
}

function Chip({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      onClick={onClick}
      className={[
        'rounded-full border px-2.5 py-1 text-xs transition',
        active ? 'border-neon/60 bg-neon-faint text-neon' : 'border-ink-600 text-zinc-400 hover:border-violet/60 hover:text-zinc-200',
      ].join(' ')}
    >
      {children}
    </button>
  );
}

'use client';

import { Handle, Position, type Node, type NodeProps } from '@xyflow/react';
import { KIND_LABEL } from '@/lib/theme';
import type { GraphNode } from '@/lib/types';

export type FileNodeData = {
  node: GraphNode;
  selected: boolean;
  dimmed: boolean;
};

export type FileFlowNode = Node<FileNodeData, 'file'>;

export default function FileNode({ data }: NodeProps<FileFlowNode>) {
  const { node, selected, dimmed } = data;
  const dir = node.path.includes('/') ? node.path.slice(0, node.path.lastIndexOf('/')) : '.';

  const ring =
    node.impact === 'direct'
      ? 'border-neon/70 shadow-neon'
      : node.impact === 'indirect'
        ? 'border-violet/70 shadow-violet'
        : 'border-ink-600';

  return (
    <div
      className={[
        'w-[230px] rounded-lg border bg-ink-900 px-3 py-2 transition-opacity',
        ring,
        selected ? 'ring-2 ring-white/70' : '',
        dimmed ? 'opacity-30' : 'opacity-100',
      ].join(' ')}
    >
      <Handle type="target" position={Position.Top} className="!h-2 !w-2 !border-0 !bg-violet" />
      <div className="flex items-center justify-between gap-2">
        <span className="truncate font-mono text-[13px] font-medium text-zinc-100" title={node.path}>
          {node.label}
        </span>
        {node.findingCount > 0 && (
          <span className="shrink-0 rounded bg-neon-faint px-1.5 py-0.5 font-mono text-[10px] text-neon">{node.findingCount}</span>
        )}
      </div>
      <div className="truncate font-mono text-[10px] text-zinc-500">{dir}</div>
      <div className="mt-1.5 flex items-center gap-1.5 text-[10px]">
        <span className="rounded bg-ink-700 px-1.5 py-0.5 uppercase tracking-wide text-zinc-300">{KIND_LABEL[node.kind]}</span>
        {node.models.length > 0 && <span className="truncate text-neon">{node.models.join(', ')}</span>}
      </div>
      <Handle type="source" position={Position.Bottom} className="!h-2 !w-2 !border-0 !bg-violet" />
    </div>
  );
}

'use client';

import { useMemo } from 'react';
import { Background, Controls, MarkerType, MiniMap, ReactFlow, type Edge } from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import { layoutGraph } from '@/lib/layout';
import { EDGE_STYLE, GREEN, PURPLE } from '@/lib/theme';
import type { Graph } from '@/lib/types';
import FileNode, { type FileFlowNode } from './FileNode';

const nodeTypes = { file: FileNode };

interface Props {
  graph: Graph;
  selectedId: string | null;
  onSelect: (id: string | null) => void;
}

export default function DependencyGraph({ graph, selectedId, onSelect }: Props) {
  const positions = useMemo(
    () =>
      layoutGraph(
        graph.nodes.map((n) => n.id),
        graph.edges.map((e): [string, string] => [e.source, e.target]),
      ),
    [graph],
  );

  const nodes = useMemo<FileFlowNode[]>(() => {
    const neighbours = new Set<string>();
    if (selectedId) {
      neighbours.add(selectedId);
      for (const e of graph.edges) {
        if (e.source === selectedId) neighbours.add(e.target);
        if (e.target === selectedId) neighbours.add(e.source);
      }
    }
    return graph.nodes.map((n) => ({
      id: n.id,
      type: 'file',
      position: positions[n.id],
      data: { node: n, selected: n.id === selectedId, dimmed: selectedId !== null && !neighbours.has(n.id) },
    }));
  }, [graph, positions, selectedId]);

  const edges = useMemo<Edge[]>(
    () =>
      graph.edges.map((e) => {
        const style = EDGE_STYLE[e.type];
        const incident = selectedId !== null && (e.source === selectedId || e.target === selectedId);
        const dimmed = selectedId !== null && !incident;
        return {
          id: e.id,
          source: e.source,
          target: e.target,
          type: 'smoothstep',
          animated: e.type === 'uses_model',
          label: e.label ?? undefined,
          labelStyle: { fill: '#c4b5fd', fontSize: 11 },
          labelBgStyle: { fill: '#0a0a0f' },
          style: {
            stroke: style.color,
            strokeWidth: incident ? 2.5 : 1.5,
            strokeDasharray: style.dashed ? '5 4' : undefined,
            opacity: dimmed ? 0.15 : 1,
          },
          markerEnd: { type: MarkerType.ArrowClosed, color: style.color },
        };
      }),
    [graph, selectedId],
  );

  if (graph.nodes.length === 0) {
    return (
      <div className="flex h-[560px] items-center justify-center rounded-xl border border-ink-600 bg-ink-900/60 text-sm text-zinc-500">
        No files to show in the graph.
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="h-[600px] overflow-hidden rounded-xl border border-ink-600">
        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={nodeTypes}
          onNodeClick={(_, node) => onSelect(node.id)}
          onPaneClick={() => onSelect(null)}
          nodesConnectable={false}
          fitView
          fitViewOptions={{ padding: 0.2 }}
          minZoom={0.1}
          colorMode="dark"
        >
          <Background color="#1a1a25" gap={22} />
          <Controls showInteractive={false} />
          <MiniMap pannable zoomable nodeColor={(n) => ((n.data as FileFlowNode['data']).node.mongo ? GREEN : PURPLE)} maskColor="rgba(5,5,7,0.7)" />
        </ReactFlow>
      </div>
      <Legend />
    </div>
  );
}

function Legend() {
  return (
    <div className="flex flex-wrap items-center gap-x-5 gap-y-1.5 px-1 text-[11px] text-zinc-400">
      <span className="flex items-center gap-1.5">
        <i className="inline-block h-2.5 w-2.5 rounded-sm border border-neon/70 shadow-neon" /> contains MongoDB code
      </span>
      <span className="flex items-center gap-1.5">
        <i className="inline-block h-2.5 w-2.5 rounded-sm border border-violet/70 shadow-violet" /> depends on MongoDB code (may need changes)
      </span>
      {(['registers_route', 'calls_service', 'uses_model', 'connects_db', 'imports'] as const).map((t) => (
        <span key={t} className="flex items-center gap-1.5">
          <i className="inline-block h-0.5 w-5" style={{ background: EDGE_STYLE[t].color }} /> {EDGE_STYLE[t].label}
        </span>
      ))}
      <span className="text-zinc-600">Arrows point from the importing file to the file it imports.</span>
    </div>
  );
}

import { CATEGORY_CLASS, CONFIDENCE_CLASS, KIND_LABEL } from '@/lib/theme';
import type { Finding, Graph, GraphNode } from '@/lib/types';

interface Props {
  node: GraphNode | null;
  graph: Graph;
  findings: Finding[];
  onSelect: (id: string) => void;
}

export default function NodeDetails({ node, graph, findings, onSelect }: Props) {
  if (!node) {
    return (
      <aside className="rounded-xl border border-ink-600 bg-ink-900/80 p-4 text-sm text-zinc-500">
        <h3 className="mb-2 text-sm font-semibold text-zinc-200">File details</h3>
        Click a file in the graph to see its MongoDB findings and which other files may need changes if it is migrated.
      </aside>
    );
  }

  const here = findings.filter((f) => f.file === node.path);
  const dependents = graph.impact[node.id] ?? [];
  const imports = graph.edges.filter((e) => e.source === node.id);
  const importedBy = graph.edges.filter((e) => e.target === node.id);

  return (
    <aside className="max-h-[680px] space-y-4 overflow-y-auto rounded-xl border border-ink-600 bg-ink-900/80 p-4">
      <div>
        <div className="break-all font-mono text-sm text-zinc-100">{node.path}</div>
        <div className="mt-1.5 flex flex-wrap gap-1.5 text-[11px]">
          <span className="rounded bg-ink-700 px-1.5 py-0.5 text-zinc-300">{KIND_LABEL[node.kind]}</span>
          <span
            className={[
              'rounded px-1.5 py-0.5',
              node.impact === 'direct' ? 'bg-neon-faint text-neon' : node.impact === 'indirect' ? 'bg-violet-faint text-violet-soft' : 'bg-ink-700 text-zinc-400',
            ].join(' ')}
          >
            {node.impact === 'direct' ? 'contains MongoDB code' : node.impact === 'indirect' ? 'depends on MongoDB code' : 'not affected'}
          </span>
        </div>
      </div>

      {dependents.length > 0 && (
        <Section title={`If this model changes, review (${dependents.length})`}>
          <ul className="space-y-1">
            {dependents.map((d) => (
              <li key={d}>
                <button onClick={() => onSelect(d)} className="break-all text-left font-mono text-[11px] text-violet-soft hover:underline">
                  {d}
                </button>
              </li>
            ))}
          </ul>
        </Section>
      )}

      <Section title={`Imports (${imports.length})`}>
        <FileList edges={imports.map((e) => e.target)} onSelect={onSelect} />
      </Section>
      <Section title={`Imported by (${importedBy.length})`}>
        <FileList edges={importedBy.map((e) => e.source)} onSelect={onSelect} />
      </Section>

      <Section title={`Findings in this file (${here.length})`}>
        {here.length === 0 ? (
          <p className="text-xs text-zinc-500">No MongoDB patterns detected.</p>
        ) : (
          <ul className="space-y-2">
            {here.map((f, i) => (
              <li key={i} className="rounded-lg border border-ink-700 bg-ink-950 p-2">
                <div className="flex flex-wrap items-center gap-1.5 text-[11px]">
                  <span className={`rounded border px-1.5 py-0.5 ${CATEGORY_CLASS[f.category]}`}>{f.category}</span>
                  <span className="font-mono text-zinc-500">line {f.line}</span>
                  <span className={`ml-auto ${CONFIDENCE_CLASS[f.confidence]}`}>{f.confidence}</span>
                </div>
                <div className="mt-1 font-mono text-xs text-zinc-200">{f.pattern}</div>
                <div className="mt-0.5 truncate font-mono text-[11px] text-zinc-500" title={f.evidence}>
                  {f.evidence}
                </div>
              </li>
            ))}
          </ul>
        )}
      </Section>
    </aside>
  );
}

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section>
      <h4 className="mb-1.5 text-[11px] font-semibold uppercase tracking-wide text-zinc-500">{title}</h4>
      {children}
    </section>
  );
}

function FileList({ edges, onSelect }: { edges: string[]; onSelect: (id: string) => void }) {
  if (edges.length === 0) return <p className="text-xs text-zinc-600">None in this graph.</p>;
  return (
    <ul className="space-y-1">
      {edges.map((id) => (
        <li key={id}>
          <button onClick={() => onSelect(id)} className="break-all text-left font-mono text-[11px] text-zinc-300 hover:text-violet-soft hover:underline">
            {id}
          </button>
        </li>
      ))}
    </ul>
  );
}

'use client';

import { useMemo, useState } from 'react';
import DependencyGraph from '@/components/DependencyGraph';
import FindingsTable from '@/components/FindingsTable';
import NodeDetails from '@/components/NodeDetails';
import PipelineHeader from '@/components/PipelineHeader';
import RepositoryForm from '@/components/RepositoryForm';
import SummaryCards from '@/components/SummaryCards';
import { analyzeRepository, analyzeSample } from '@/lib/api';
import type { AnalysisResponse, AnalyzeRequest } from '@/lib/types';

type Tab = 'graph' | 'findings';

export default function Home() {
  const [result, setResult] = useState<AnalysisResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [tab, setTab] = useState<Tab>('graph');
  const [selectedId, setSelectedId] = useState<string | null>(null);

  async function run(task: () => Promise<AnalysisResponse>) {
    setLoading(true);
    setError(null);
    try {
      const data = await task();
      setResult(data);
      setSelectedId(null);
      setTab(data.graph ? 'graph' : 'findings');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Something went wrong.');
    } finally {
      setLoading(false);
    }
  }

  const selectedNode = useMemo(
    () => result?.graph?.nodes.find((n) => n.id === selectedId) ?? null,
    [result, selectedId],
  );

  function openFile(file: string) {
    if (result?.graph?.nodes.some((n) => n.id === file)) {
      setSelectedId(file);
      setTab('graph');
    }
  }

  return (
    <main className="mx-auto max-w-7xl space-y-6 px-4 py-8 sm:px-6">
      <header className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">
            Migrate<span className="text-neon">AI</span>
          </h1>
          <p className="text-sm text-zinc-400">AI-powered software migration workspace</p>
        </div>
        <span className="rounded-full border border-violet/50 bg-violet-faint px-3 py-1 font-mono text-[11px] text-violet-soft">MVP · scanner + Agent 1</span>
      </header>

      <PipelineHeader loading={loading} hasResult={result !== null} />

      <RepositoryForm
        loading={loading}
        onAnalyze={(req: AnalyzeRequest) => run(() => analyzeRepository(req))}
        onSample={() => run(analyzeSample)}
      />

      {error && (
        <div role="alert" className="rounded-lg border border-red-500/40 bg-red-500/10 px-4 py-3 text-sm text-red-300">
          {error}
        </div>
      )}

      {loading && (
        <div className="rounded-xl border border-violet/40 bg-violet-faint px-4 py-6 text-center text-sm text-violet-soft">
          Fetching the repository, scanning for MongoDB code and building the dependency graph…
        </div>
      )}

      {result && !loading && (
        <>
          <div className="flex flex-wrap items-center gap-2 text-xs text-zinc-500">
            <span className="h-1.5 w-1.5 rounded-full bg-neon" />
            Analysis complete for{' '}
            <span className="font-mono text-zinc-300">
              {result.source === 'sample' ? 'bundled sample app' : `${result.repositoryUrl}${result.branch ? ` @ ${result.branch}` : ''}`}
            </span>
          </div>

          <SummaryCards summary={result.summary} warnings={result.warnings} />

          <div className="flex gap-1 border-b border-ink-700">
            <TabButton active={tab === 'graph'} onClick={() => setTab('graph')} disabled={!result.graph}>
              Dependency graph
            </TabButton>
            <TabButton active={tab === 'findings'} onClick={() => setTab('findings')}>
              Findings ({result.summary.totalFindings})
            </TabButton>
          </div>

          {tab === 'graph' && result.graph && (
            <div className="grid gap-4 lg:grid-cols-[1fr_340px]">
              <DependencyGraph graph={result.graph} selectedId={selectedId} onSelect={setSelectedId} />
              <NodeDetails node={selectedNode} graph={result.graph} findings={result.findings} onSelect={setSelectedId} />
            </div>
          )}
          {tab === 'findings' && <FindingsTable findings={result.findings} onOpenFile={openFile} />}
        </>
      )}
    </main>
  );
}

function TabButton({
  active,
  disabled,
  onClick,
  children,
}: {
  active: boolean;
  disabled?: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={[
        '-mb-px border-b-2 px-4 py-2 text-sm transition',
        active ? 'border-violet text-violet-soft' : 'border-transparent text-zinc-400 hover:text-zinc-200',
        disabled ? 'cursor-not-allowed opacity-40' : '',
      ].join(' ')}
    >
      {children}
    </button>
  );
}
